import { CODE_1_CONTROLLER } from './scripts/controller';
import { CODE_2_AUTH_AND_ADMIN } from './scripts/auth';
import { CODE_3_CORE_OPERATIONS } from './scripts/core';
import { CODE_4_SUPPORT_MODULE } from './scripts/support';
import { CODE_5_LIB_AND_UTILS } from './scripts/utils';

export const BACKEND_FILES: Record<string, string> = {
    '1_Controller.gs': CODE_1_CONTROLLER,
    '2_AuthAndAdmin.gs': CODE_2_AUTH_AND_ADMIN,
    '3_CoreOperations.gs': CODE_3_CORE_OPERATIONS,
    '4_SupportModule.gs': CODE_4_SUPPORT_MODULE,
    '5_LibAndUtils.gs': `/**
 * 5_LibAndUtils.gs - Helpers, Robust Email Engine & PDF Templates
 */

const ResponseBuilder = {
  success: function(data = {}) { return this.build({ status: "success", ...data }); },
  error: function(message, code = null) {
    const response = { status: "error", message: message };
    if (code) response.code = code;
    return this.build(response);
  },
  build: function(data) {
    return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
  }
};

const Validation = {
  updateFromRow: function(ss, body) {
     try {
       const row = body.row;
       const sheetName = body.sheet;
       let truck, trailer, driver, inspector, location;
       if (sheetName === 'General') {
           truck = row[2]; trailer = row[3]; inspector = row[4]; driver = row[5]; location = row[6];
       } else {
           truck = row[2]; trailer = row[3]; location = row[5]; inspector = row[7]; driver = row[8];
       }
       this.updateSingle(ss, 'Truck_Reg_No', truck);
       this.updateSingle(ss, 'Trailer_Reg_No', trailer);
       this.updateSingle(ss, 'Driver_Name', driver);
       this.updateSingle(ss, 'Inspector_Name', inspector);
       this.updateSingle(ss, 'Location', location);
     } catch (e) {}
  },
  updateSingle: function(ss, headerName, value) {
     if (!value || String(value).trim() === "") return;
     const valStr = String(value).trim();
     let vSheet = ss.getSheetByName('Validation_Data');
     if (!vSheet) {
        vSheet = ss.insertSheet('Validation_Data');
        vSheet.appendRow(['Truck_Reg_No', 'Trailer_Reg_No', 'Driver_Name', 'Inspector_Name', 'Location', 'Position']);
        vSheet.setFrozenRows(1);
     }
     const headers = vSheet.getRange(1, 1, 1, vSheet.getLastColumn()).getValues()[0];
     let colIndex = headers.indexOf(headerName) + 1;
     if (colIndex < 1) {
         colIndex = headers.length + 1;
         vSheet.getRange(1, colIndex).setValue(headerName);
     }
     const fullCol = vSheet.getRange(1, colIndex, vSheet.getMaxRows(), 1).getValues().flat().map(String);
     if (!fullCol.includes(valStr)) {
         let targetRow = 1;
         for(let i=1; i<fullCol.length; i++) {
             if(fullCol[i] === "") { targetRow = i + 1; break; }
         }
         if (targetRow === 1) targetRow = vSheet.getLastRow() + 1;
         vSheet.getRange(targetRow, colIndex).setValue(valStr);
     }
  }
};

const Logger = {
  log: function(ss, action, details) {
    let logSheet = ss.getSheetByName('System_Logs');
    if (!logSheet) {
        logSheet = ss.insertSheet('System_Logs');
        logSheet.appendRow(["Timestamp", "Action", "Details"]);
        logSheet.setFrozenRows(1);
    }
    logSheet.appendRow([new Date(), action, details]);
  }
};

const EmailHandlers = {
  sendEmailNotifications: function(ss, data, moduleName) {
    Logger.log(ss, "EMAIL_START", "Triggering for: " + moduleName);

    try {
      var recipients = [];
      var userSheet = ss.getSheetByName("Users");

      if (userSheet) {
          var users = userSheet.getDataRange().getValues();
          for (var i = 1; i < users.length; i++) {
             var userEmail = String(users[i][1]).trim(); 
             var rawPrefs = users[i][7];

             if (userEmail && userEmail.indexOf("@") > -1) {
                 try {
                     var prefs = rawPrefs ? JSON.parse(rawPrefs) : {};
                     var emailsEnabled = (prefs.emailNotifications !== false); 

                     if (emailsEnabled) {
                         var shouldSend = false;
                         if (moduleName === "General" && (prefs.notifyGeneral !== false)) shouldSend = true;
                         else if (moduleName === "Petroleum" && (prefs.notifyPetroleum !== false)) shouldSend = true;
                         else if (moduleName === "Petroleum_V2" && (prefs.notifyPetroleumV2 !== false)) shouldSend = true;
                         else if (moduleName === "Acid" && (prefs.notifyAcid !== false)) shouldSend = true;
                         else if (prefs.notifyGeneral !== false) shouldSend = true; // Safe default

                         if (shouldSend) recipients.push(userEmail);
                     }
                 } catch(e) { recipients.push(userEmail); }
             }
          }
      }

      // FALLBACK: If no registered users with alerts, send to Manager Email
      if (recipients.length === 0) {
          var settingsSheet = ss.getSheetByName("System_Settings");
          if (settingsSheet && settingsSheet.getLastRow() >= 2) {
              var mgrEmail = settingsSheet.getRange(2, 2).getValue();
              if (mgrEmail && String(mgrEmail).indexOf("@") > -1) {
                  recipients.push(String(mgrEmail).trim());
                  Logger.log(ss, "EMAIL_FALLBACK", "Using Manager Email: " + mgrEmail);
              }
          }
      }

      if (recipients.length === 0) {
          Logger.log(ss, "EMAIL_ABORT", "No valid recipients found in database.");
          return;
      }

      var row = data.row;
      var truckNo = "N/A", inspector = "N/A", rating = "N/A";

      if (moduleName === "General") {
          truckNo = row[2] || "UNIT"; inspector = row[4] || "Inspector"; rating = row[8] || "0";
      } else {
          truckNo = row[2] || "UNIT"; inspector = row[7] || "Inspector"; rating = row[9] || "0";
      }

      var statusColor = "#10b981";
      var statusText = "PASSED";
      if (rating <= 3) { statusColor = "#f59e0b"; statusText = "WARNING"; } 
      if (rating <= 2) { statusColor = "#ef4444"; statusText = "CRITICAL FAIL"; }

      var htmlBody = 
          "<div style='font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden; background-color: #ffffff;'>" +
              "<div style='background-color: #0f172a; padding: 30px; text-align: center;'>" +
                  "<h2 style='color: white; margin: 0; font-size: 18px; font-weight: 800; letter-spacing: 2px; text-transform: uppercase;'>Safety Alert System</h2>" +
              "</div>" +
              "<div style='padding: 30px; color: #1e293b;'>" +
                  "<p style='margin-top: 0; font-size: 14px;'>A new <strong>" + moduleName + "</strong> audit has been synchronized with the fleet registry.</p>" +
                  "<div style='background-color: #f8fafc; padding: 25px; border-radius: 12px; border: 1px solid #f1f5f9; margin: 25px 0;'>" +
                      "<table style='width: 100%; border-collapse: collapse;'>" +
                          "<tr>" +
                              "<td style='padding: 8px 0; color: #94a3b8; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px;'>Asset Registration</td>" +
                              "<td style='padding: 8px 0; color: #0f172a; font-size: 15px; font-weight: 800; text-align: right;'>" + truckNo + "</td>" +
                          "</tr>" +
                          "<tr>" +
                              "<td style='padding: 8px 0; color: #94a3b8; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px;'>Auditor</td>" +
                              "<td style='padding: 8px 0; color: #0f172a; font-size: 15px; font-weight: 600; text-align: right;'>" + inspector + "</td>" +
                          "</tr>" +
                          "<tr>" +
                              "<td style='padding: 8px 0; color: #94a3b8; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px;'>Safety Rating</td>" +
                              "<td style='padding: 8px 0; text-align: right;'>" +
                                  "<span style='color: " + statusColor + "; font-weight: 900; font-size: 16px;'>" + statusText + " (" + rating + "/5)</span>" +
                              "</td>" +
                          "</tr>" +
                      "</table>" +
                  "</div>" +
                  "<p style='font-size: 13px; line-height: 1.6; color: #64748b;'>An official digital transcript of this audit is attached for your records. Please review critical faults immediately to mitigate fleet risks.</p>" +
                  "<div style='margin-top: 30px; padding-top: 20px; border-top: 1px solid #f1f5f9; text-align: center;'>" +
                      "<p style='font-size: 10px; color: #cbd5e1; text-transform: uppercase; letter-spacing: 1px; margin: 0;'>Automated Payload: No Reply Required</p>" +
                  "</div>" +
              "</div>" +
          "</div>";

      var blobs = [];
      if (data.reportData) {
          try {
              var reportHtml = PDFGenerator.create(data.reportData);
              var pdfBlob = Utilities.newBlob(reportHtml, 'text/html')
                  .getAs('application/pdf')
                  .setName(String(truckNo).replace(/\\s/g, '_') + '_' + moduleName + '_Report.pdf');
              blobs.push(pdfBlob);
          } catch (e) { Logger.log(ss, "PDF_GEN_FAIL", e.toString()); }
      }

      var subject = "Audit Report: " + truckNo + " [" + statusText + "]";
      var emailOptions = {
          htmlBody: htmlBody,
          name: "SafetyCheck Alerts", 
          attachments: blobs
      };

      if (recipients.length > 1) {
          emailOptions.bcc = recipients.slice(1).join(",");
      }

      GmailApp.sendEmail(recipients[0], subject, "HTML Required", emailOptions);
      Logger.log(ss, "EMAIL_DISPATCHED", "To: " + recipients[0] + " + " + (recipients.length-1) + " others.");

    } catch (err) {
        Logger.log(ss, "EMAIL_SYSTEM_FATAL", err.toString());
    }
  },

  sendInvitation: function(email, role, orgName) {
    const subject = "Access Invitation: " + orgName;
    const htmlBody = '<div style="font-family: Arial, sans-serif; padding: 32px; border: 1px solid #f1f5f9; border-radius: 20px; max-width: 600px; color: #0f172a; background: #ffffff;">' +
      '<h2 style="color: #4f46e5; margin-bottom: 20px; font-size: 22px; font-weight: 800; letter-spacing: -0.02em;">Welcome to the Portal</h2>' +
      '<p style="font-size: 15px; line-height: 1.6; color: #475569;">You have been enrolled as a fleet auditor for <strong>' + orgName + '</strong>.</p>' +
      '<div style="background: #f8fafc; padding: 24px; border-radius: 16px; margin: 24px 0; border: 1px solid #f1f5f9;">' +
        '<p style="margin: 0 0 10px 0; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 1px;">Access Credentials</p>' +
        '<p style="margin: 0; font-size: 14px; font-weight: 600;">Role: ' + role + '</p>' +
        '<p style="margin: 4px 0 0 0; font-size: 14px; font-weight: 600;">ID: ' + email + '</p>' +
      '</div>' +
      '<p style="font-size: 14px; line-height: 1.6; color: #64748b;">Sign in with your email. Leave the password blank for your initial setup.</p>' +
    '</div>';

    try {
      MailApp.sendEmail(email, subject, "Invitation", { htmlBody: htmlBody });
    } catch (e) {}
  }
};

const PDFGenerator = {
  create: function(data) {
    if (data.title && (data.title.indexOf('General') > -1 || data.title.indexOf('GENERAL') > -1)) {
       return this.createGeneralReport(data);
    }
    if (data.title && data.title.indexOf('Petroleum Tanker Inspection V2') > -1) {
       return this.createPetroleumV2Report(data);
    }
    if (data.title && data.title.indexOf('Petroleum Tanker Inspection') > -1) {
       return this.createPetroleumReport(data);
    }
    if (data.title && data.title.indexOf('Acid Tanker Inspection') > -1) {
       return this.createAcidReport(data);
    }
    return this.createGenericReport(data);
  },

  createAcidReport: function(data) {
      var dateStr = new Date(data.timestamp).toLocaleString('en-GB');
      var itemsHtml = "";
      var currentCategory = "";
      (data.items || []).forEach(function(item) {
          var headerText = item.category;
          if (headerText !== currentCategory) {
              currentCategory = headerText;
              itemsHtml += "<tr><td colspan='3' style='background-color:#f1f5f9; font-weight:bold; border:1px solid #cbd5e1; padding:8px; font-size:10px; text-transform:uppercase;'>" + currentCategory + "</td></tr>";
          }
          var statusStyle = item.status === 'Bad' ? "color:#ef4444;font-weight:800;" : "";
          itemsHtml += "<tr>" +
              "<td style='border:1px solid #e2e8f0; padding:6px; text-align:center; color:#94a3b8;'>•</td>" +
              "<td style='border:1px solid #e2e8f0; padding:6px 10px; font-size:11px;'>" + item.label + "</td>" +
              "<td style='border:1px solid #e2e8f0; padding:6px 10px; font-size:11px; " + statusStyle + "'>" + (item.status || "") + "</td>" +
              "</tr>";
      });
      return "<html><body style='font-family: sans-serif;'>" +
          "<h2 style='text-align:center; color:#0f172a; text-transform:uppercase;'>Acid Tanker Checklist</h2>" +
          "<div style='margin-bottom:20px; font-size:12px; border-bottom:1px solid #eee; padding-bottom:10px;'><b>Asset:</b> " + data.truckNo + " | <b>Trailer:</b> " + data.trailerNo + " | <b>Timestamp:</b> " + dateStr + "</div>" +
          "<table style='width:100%; border-collapse:collapse;'>" + itemsHtml + "</table>" +
          "<div style='margin-top:30px; padding:15px; background:#f8fafc; border-radius:8px;'><b>Inspector Comments:</b><br/>" + data.remarks + "</div>" +
          "</body></html>";
  },

  createPetroleumV2Report: function(data) {
      var dateStr = new Date(data.timestamp).toLocaleString('en-GB');
      var itemsHtml = "";
      var currentCategory = "";
      (data.items || []).forEach(function(item) {
          if (item.category !== currentCategory) {
              currentCategory = item.category;
              itemsHtml += "<tr><td colspan='3' style='background-color:#1e293b; color:white; font-weight:bold; border:1px solid #000; padding:8px; text-align:center; text-transform:uppercase; font-size:10px;'>" + currentCategory + "</td></tr>";
          }
          itemsHtml += "<tr>" +
              "<td style='border:1px solid #ccc; padding:6px 10px; width:70%; font-size:11px;'>" + item.label + "</td>" +
              "<td style='border:1px solid #ccc; padding:6px; text-align:center; font-weight:bold;'>" + (item.status === 'Good' ? 'YES' : '-') + "</td>" +
              "<td style='border:1px solid #ccc; padding:6px; text-align:center; color:red; font-weight:bold;'>" + (item.status === 'Bad' ? 'NO' : '-') + "</td>" +
              "</tr>";
      });
      return "<html><body style='font-family:Helvetica; padding:30px;'>" +
          "<h1 style='text-align:center; color:#0f172a; font-size:24px;'>PETROLEUM V2 AUDIT</h1>" +
          "<div style='border:1px solid #e2e8f0; padding:15px; margin-bottom:20px; border-radius:8px; background:#f8fafc;'><b>Asset Identification:</b> " + data.truckNo + " (" + data.trailerNo + ") <br/><b>Sync Time:</b> " + dateStr + "</div>" +
          "<table style='width:100%; border-collapse:collapse;'>" + itemsHtml + "</table>" +
          "</body></html>";
  },

  createGeneralReport: function(data) {
      var dateStr = new Date(data.timestamp).toLocaleString('en-GB');
      var itemsHtml = "";
      (data.items || []).forEach(function(item) {
          itemsHtml += "<tr><td style='border-bottom:1px solid #f1f5f9; padding:10px; color:#475569; font-size:11px;'>" + item.label + "</td><td style='border-bottom:1px solid #f1f5f9; padding:10px; text-align:right; font-weight:bold; color:#0f172a; font-size:11px;'>" + item.status + "</td></tr>";
      });
      return "<html><body style='font-family:Arial; padding:40px; color:#1e293b;'>" +
          "<div style='text-align:center; border-bottom:4px solid #0f172a; padding-bottom:20px; margin-bottom:30px;'>" +
          "<h2 style='margin:0; letter-spacing:1px;'>VEHICLE INSPECTION LOG</h2><p style='color:#94a3b8; font-size:12px; margin-top:5px;'>" + dateStr + "</p></div>" +
          "<div style='margin-bottom:30px; font-size:13px;'><b>Asset:</b> " + data.truckNo + " <br/><b>Auditor:</b> " + data.inspectedBy + "</div>" +
          "<table style='width:100%; border-collapse:collapse;'>" + itemsHtml + "</table>" +
          "<div style='margin-top:40px; background:#f8fafc; padding:20px; border-radius:12px; border:1px solid #f1f5f9;'>" +
          "<b>Operational Status:</b> " + (data.safeToLoad === 'Yes' ? 'CLEAR FOR DISPATCH' : 'GROUNDED') + "<br/><b>Remarks:</b> " + data.remarks + "</div>" +
          "</body></html>";
  },

  createGenericReport: function(data) {
    return "<html><body><h1>" + data.title + "</h1><p>Date: " + data.timestamp + "</p></body></html>";
  }
};`
};

export const BACKEND_SCRIPT_TEMPLATE = Object.values(BACKEND_FILES).join('\n\n');

import React from 'react';

interface SubmissionOverlayProps {
    status: 'idle' | 'submitting' | 'success' | 'offline_saved';
    onClose?: () => void;
    onViewReport?: () => void;
    aiAnalysis?: string | null;
}

const SubmissionOverlay: React.FC<SubmissionOverlayProps> = ({ status, onClose, onViewReport, aiAnalysis }) => {
    if (status === 'idle') return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center overflow-y-auto py-10">
            {/* Backdrop with Blur */}
            <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md transition-all duration-300"></div>

            {/* Content Card */}
            <div className={`relative bg-white rounded-3xl shadow-2xl p-6 sm:p-8 w-full mx-4 text-center transform transition-all duration-300 scale-100 animate-fadeIn border border-white/20 max-w-xl my-auto`}>

                {status === 'submitting' && (
                    <div className="flex flex-col items-center gap-4 py-10">
                        <div className="relative">
                            <div className="w-16 h-16 border-4 border-blue-100 border-t-blue-600 rounded-full animate-spin"></div>
                            <div className="absolute inset-0 flex items-center justify-center">
                                <svg className="w-6 h-6 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"></path></svg>
                            </div>
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-gray-900 uppercase tracking-tight">Uploading Inspection</h3>
                            <p className="text-xs text-gray-500 mt-1 font-medium uppercase tracking-widest opacity-60">Syncing with Fleet Database...</p>
                        </div>
                    </div>
                )}

                {status === 'success' && (
                    <div className="flex flex-col items-center gap-6 py-4 animate-fadeIn">
                        <div className="w-16 h-16 bg-emerald-100 rounded-full flex items-center justify-center shadow-inner">
                            <svg className="w-8 h-8 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
                        </div>

                        <div>
                            <h3 className="text-xl font-black text-gray-900 uppercase tracking-tighter">Submission Successful</h3>
                            <p className="text-[10px] text-slate-500 mt-1 font-bold uppercase tracking-[0.2em]">Dispatching Digital Reports...</p>
                        </div>

                        {/* AI ANALYSIS SECTION */}
                        <div className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-5 text-left relative overflow-hidden">
                            <div className="flex items-center gap-2 mb-4">
                                <div className="w-6 h-6 bg-indigo-600 rounded-lg flex items-center justify-center text-white">
                                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                                </div>
                                <h4 className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.2em]">Safety AI Insights</h4>
                            </div>

                            {!aiAnalysis ? (
                                <div className="flex flex-col items-center py-6 gap-3">
                                    <svg className="animate-spin h-5 w-5 text-indigo-400" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest animate-pulse">Analyzing Vehicle Condition...</p>
                                </div>
                            ) : (
                                <div className="animate-fadeIn">
                                    <p className="text-xs font-medium text-slate-700 leading-relaxed whitespace-pre-wrap">
                                        {aiAnalysis}
                                    </p>
                                    <p className="mt-4 text-[9px] text-slate-400 font-bold uppercase tracking-widest border-t border-slate-100 pt-3">
                                        Report logged to central cloud registry
                                    </p>
                                </div>
                            )}
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full">
                            <button 
                                onClick={onViewReport}
                                className="w-full py-4 bg-white border border-slate-200 text-slate-700 font-bold rounded-xl shadow-sm hover:bg-slate-50 transition-all flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest"
                            >
                                <svg className="w-4 h-4 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2"><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                                Digital PDF
                            </button>
                            <button 
                                onClick={onClose}
                                className="w-full py-4 bg-slate-900 text-white font-black rounded-xl shadow-lg hover:bg-black transition-all flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest active:scale-95"
                            >
                                Return Home
                            </button>
                        </div>
                    </div>
                )}

                {status === 'offline_saved' && (
                    <div className="flex flex-col items-center gap-4 py-10">
                        <div className="w-16 h-16 bg-amber-100 rounded-full flex items-center justify-center shadow-inner">
                            <svg className="w-10 h-10 text-amber-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
                        </div>
                        <div>
                            <h3 className="text-xl font-black text-gray-900 uppercase tracking-tighter">Offline Saved</h3>
                            <p className="text-sm text-gray-500 mt-2 leading-relaxed font-medium">
                                Data stored on-device. Sync will resume automatically when internet returns.
                            </p>
                        </div>
                        <button 
                            onClick={onClose}
                            className="w-full mt-4 py-4 bg-slate-100 text-slate-600 font-bold rounded-xl hover:bg-slate-200 transition-all text-[10px] uppercase tracking-widest"
                        >
                            Got It
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

export default SubmissionOverlay;

import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_DATA, InspectionData, User } from './types';
import { 
    SHEET_HEADERS, PETROLEUM_HEADERS, PETROLEUM_V2_HEADERS, ACID_HEADERS,
    INSPECTION_ITEMS, PETROLEUM_INSPECTION_ITEMS, PETROLEUM_V2_ITEMS, ACID_INSPECTION_ITEMS
} from './constants';

// Hooks
import { useAuth } from './hooks/useAuth';
import { useSettings } from './hooks/useSettings';
import { useNotifications } from './hooks/useNotifications';
import { useHistory } from './hooks/useHistory';
import { useOfflineSync } from './hooks/useOfflineSync';
import { useSubscription } from './hooks/useSubscription';

// Services
import { analyzeInspection } from './services/geminiService';

// UI Components
import Toast from './components/ui/Toast';
import SubmissionOverlay from './components/ui/SubmissionOverlay';
import SystemTour from './components/ui/SystemTour'; 
import InstallPwaPrompt from './components/ui/InstallPwaPrompt';
import OnboardingWizard from './components/ui/OnboardingWizard'; 
import ChatAssistant from './components/ui/ChatAssistant';

// Layout Components
import AppHeader from './components/layout/AppHeader';
import AppContent from './components/layout/AppContent';
import AppModals from './components/layout/AppModals';
import AppFooter from './components/layout/AppFooter';

// Views
import LoginView from './views/LoginView';

// Main Application Logic
const App = () => {
  // Core Business Hooks
  const { currentUser, setCurrentUser, handleLogin, handleLogout, sessionExpired, setSessionExpired } = useAuth();
  const { settings, setSettings, appScriptUrl, setAppScriptUrl, isSavingSettings, handleSaveSettings, fetchSystemSettings } = useSettings();
  const { subscription, history: subHistory, refreshSubscription } = useSubscription(appScriptUrl, currentUser);

  // View Routing State
  const [activeModule, setActiveModule] = useState('overview'); 
  const [viewMode, setViewMode] = useState<'dashboard' | 'form'>('dashboard');

  // UI Interaction State
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [isSolutionsOpen, setIsSolutionsOpen] = useState(false);
  const [isRequestModalOpen, setIsRequestModalOpen] = useState(false);
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [isStartModalOpen, setIsStartModalOpen] = useState(false);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error' | 'info' | 'warning'} | null>(null);
  const [showTour, setShowTour] = useState(false);
  const [isCheckingMaint, setIsCheckingMaint] = useState(false);

  // Data Handlers State
  const [lastSubmittedData, setLastSubmittedData] = useState<InspectionData | null>(null);
  const [aiAnalysisResult, setAiAnalysisResult] = useState<string | null>(null);
  const [selectedReportData, setSelectedReportData] = useState<InspectionData | null>(null);
  const [formInitialData, setFormInitialData] = useState<InspectionData>(INITIAL_DATA);
  const [supportPrefill, setSupportPrefill] = useState<{subject: string, description: string} | null>(null);
  const [pendingModule, setPendingModule] = useState<string | null>(null);
  const [hasExistingDraft, setHasExistingDraft] = useState(false);

  // Core Data Fetching Hook
  const { historyList, isLoadingHistory, validationLists, stats, fetchHistory } = useHistory(appScriptUrl, activeModule, currentUser);

  // Handlers
  const showToast = (message: string, type: 'success' | 'error' | 'info' | 'warning') => {
      setToast({ message, type });
      setTimeout(() => setToast(null), 4000);
  };

  const { submissionStatus, setSubmissionStatus, isSyncing, addToQueue } = useOfflineSync(appScriptUrl, showToast, () => fetchHistory(true));

  const lockInfo = useMemo(() => {
      const isSuperAdmin = currentUser?.role === 'SuperAdmin';
      const isSubExpired = subscription ? (subscription.status === 'Expired' || subscription.daysRemaining <= 0) : false;
      const isMaintActive = settings.maintenanceMode === true;
      if (isSuperAdmin) return { isLocked: false, reason: null as any };
      if (isMaintActive) return { isLocked: true, reason: 'maintenance' as const };
      if (isSubExpired) return { isLocked: true, reason: 'license' as const };
      return { isLocked: false, reason: null as any };
  }, [subscription, settings.maintenanceMode, currentUser?.role]);

  const isSystemLocked = lockInfo.isLocked;

  useEffect(() => {
    (window as any).isSubscriptionLocked = isSystemLocked;
  }, [isSystemLocked]);

  useEffect(() => {
    if (currentUser && !currentUser.needsSetup) {
        setActiveModule('overview');
        setViewMode('dashboard');
    }
  }, [currentUser?.username, currentUser?.needsSetup]);

  useEffect(() => {
      if (sessionExpired === 'idle') showToast("Session expired due to inactivity.", 'warning');
      else if (sessionExpired === 'max_duration') showToast("Session limit reached. Log in again.", 'info');
      if (sessionExpired) setSessionExpired(null);
  }, [sessionExpired]);

  const handleNavigate = async (module: string) => {
    if (module.startsWith('support:info:')) {
        const solutionName = module.replace('support:info:', '');
        setSupportPrefill({
            subject: `Inquiry: ${solutionName}`,
            description: `Automated Request: User is interested in learning more about integrating the "${solutionName}" module into the current fleet workflow.`
        });
        setActiveModule('support');
        setViewMode('dashboard');
        setIsSolutionsOpen(false);
        return;
    }

    if (module.startsWith('request:start_inspection')) {
        if (isSystemLocked) { showToast("System is in View-Only mode.", "error"); return; }
        const parts = module.split('|');
        const type = parts[1]?.toLowerCase();
        const truck = parts[2];
        const trailer = parts[3];
        const requester = parts[4];
        const reason = parts[5];
        let moduleKey = 'general';
        if (type === 'petroleum') moduleKey = 'petroleum';
        else if (type === 'petroleum_v2') moduleKey = 'petroleum_v2';
        else if (type === 'acid') moduleKey = 'acid';

        setActiveModule(moduleKey);
        startFreshInspection(moduleKey, {
            truckNo: truck,
            trailerNo: trailer,
            remarks: `Requested by ${requester}: ${reason}`,
            requestId: parts[0].split('-')[1]
        });
        return;
    }

    if (module !== 'support') setSupportPrefill(null);
    setActiveModule(module);
    setViewMode('dashboard');
  };

  const handleOpenInspectionFlow = (module: string) => {
    if (isSystemLocked) { showToast("System is currently in view-only mode.", "error"); return; }
    const draftKey = `sc_draft_${module}`;
    const draft = localStorage.getItem(draftKey);
    if (draft) {
        setPendingModule(module);
        setHasExistingDraft(true);
        setIsStartModalOpen(true);
    } else {
        startFreshInspection(module);
    }
  };

  const { notifications, handleMarkNotificationRead, handleDismissNotification, handleClearAllNotifications, handleGlobalAcknowledge } = useNotifications(appScriptUrl, currentUser, showToast);

  const startFreshInspection = (module: string, prefill?: Partial<InspectionData>) => {
      if (isSystemLocked) { showToast("Access Restricted: View-Only mode active.", "error"); return; }
      setLastSubmittedData(null);
      setAiAnalysisResult(null);
      setFormInitialData({ ...INITIAL_DATA, timestamp: new Date().toISOString(), inspectedBy: currentUser?.name || '', ...prefill });
      setViewMode('form');
  };

  const handleResumeDraft = () => {
    if (!pendingModule) return;
    const draftKey = `sc_draft_${pendingModule}`;
    const draftData = localStorage.getItem(draftKey);
    if (draftData) {
        setFormInitialData(JSON.parse(draftData));
        setActiveModule(pendingModule);
        setViewMode('form');
    }
    setIsStartModalOpen(false);
  };

  const handleDiscardAndStartNew = () => {
    if (!pendingModule) return;
    localStorage.removeItem(`sc_draft_${pendingModule}`);
    setActiveModule(pendingModule);
    startFreshInspection(pendingModule);
    setIsStartModalOpen(false);
  };

  const handleSaveDraft = (data: InspectionData) => {
    localStorage.setItem(`sc_draft_${activeModule}`, JSON.stringify(data));
    setViewMode('dashboard');
  };

  const handleExitForm = () => setViewMode('dashboard');

  const handleGoogleSheetSubmit = async (formData: InspectionData) => {
    if (isSystemLocked) { showToast("System is in View-Only mode. Submission blocked.", "error"); return; }
    if (!appScriptUrl) { showToast("Application URL not configured", "error"); return; }

    setSubmissionStatus('submitting');
    setLastSubmittedData(formData);
    setAiAnalysisResult(null);

    let sheetName = 'General', headers = SHEET_HEADERS, moduleTitle = "General Vehicle Inspection", activeItems = INSPECTION_ITEMS;
    if (activeModule === 'petroleum') { 
        sheetName = 'Petroleum'; headers = PETROLEUM_HEADERS; moduleTitle = "Petroleum Tanker Inspection"; activeItems = PETROLEUM_INSPECTION_ITEMS;
    } else if (activeModule === 'petroleum_v2') { 
        sheetName = 'Petroleum_V2'; headers = PETROLEUM_V2_HEADERS; moduleTitle = "Petroleum Tanker Inspection V2"; activeItems = PETROLEUM_V2_ITEMS;
    } else if (activeModule === 'acid') { 
        sheetName = 'Acid'; headers = ACID_HEADERS; moduleTitle = "Acid Tanker Inspection"; activeItems = ACID_INSPECTION_ITEMS;
    }

    const row = headers.map(h => formData[h] !== undefined ? formData[h] : "");

    // Explicitly define report data to avoid undefined fields in Apps Script
    const reportData = {
        title: moduleTitle, 
        timestamp: formData.timestamp || new Date().toISOString(), 
        truckNo: formData.truckNo || 'N/A', 
        trailerNo: formData.trailerNo || 'N/A', 
        jobCard: formData.jobCard || '',
        location: formData.location || 'N/A', 
        odometer: formData.odometer || '0', 
        inspectedBy: formData.inspectedBy || currentUser?.name || 'Inspector', 
        driverName: formData.driverName || 'N/A',
        remarks: formData.remarks || '', 
        rate: formData.rate || 0, 
        safeToLoad: formData.safeToLoad || 'Not Specified', 
        signatures: { 
            inspector: formData.inspectorSignature || null, 
            driver: formData.driverSignature || null 
        },
        photos: { 
            front: formData.photoFront || null, 
            ls: formData.photoLS || null, 
            rs: formData.photoRS || null, 
            back: formData.photoBack || null, 
            damage: formData.photoDamage || null 
        },
        items: activeItems.map(item => ({ 
            label: item.label, 
            category: item.category, 
            status: formData[item.id] || 'N/A' 
        })),
        companyName: settings.companyName || 'Fleet Portal', 
        companyLogo: settings.companyLogo || null
    };

    const payload = { 
        action: 'create', 
        sheet: sheetName, 
        headers: headers, 
        row: row, 
        requestId: formData.requestId || null, 
        reportData: reportData 
    };

    if (!navigator.onLine) {
        addToQueue(payload); 
        localStorage.removeItem(`sc_draft_${activeModule}`);
        setSubmissionStatus('offline_saved'); 
        setTimeout(() => { setSubmissionStatus('idle'); setViewMode('dashboard'); }, 3500); 
        return;
    }

    try {
        await fetch(appScriptUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
        setSubmissionStatus('success'); 
        localStorage.removeItem(`sc_draft_${activeModule}`);
        try { 
            const analysis = await analyzeInspection(formData); 
            setAiAnalysisResult(analysis); 
        } catch (aiErr) { 
            setAiAnalysisResult("AI analysis currently unavailable."); 
        }
        fetchHistory(true); 
    } catch (error) {
        addToQueue(payload); 
        localStorage.removeItem(`sc_draft_${activeModule}`);
        setSubmissionStatus('offline_saved'); 
        setTimeout(() => { setSubmissionStatus('idle'); setViewMode('dashboard'); }, 3500);
    }
  };

  const handleRequestSubmit = async (data: any) => {
      if (isSystemLocked) { showToast("Requests are disabled in View-Only mode.", "error"); return; }
      if (!appScriptUrl) return;
      try { await fetch(appScriptUrl, { method: 'POST', body: JSON.stringify({ action: 'request_inspection', requester: currentUser?.name, role: currentUser?.role, ...data }), mode: 'no-cors' }); showToast("Inspection request submitted successfully", "success"); } catch (e) { showToast("Failed to submit request", "error"); }
  };

  const handleViewReport = (item: InspectionData | null) => {
    setSelectedReportData(item);
    setIsReportModalOpen(true);
  };

  const handleOnboardingComplete = (updatedUser: User) => {
      const userWithSetup = { ...updatedUser, needsSetup: false };
      setCurrentUser(userWithSetup);
      localStorage.setItem('safetyCheck_user', JSON.stringify(userWithSetup));
      setActiveModule('overview'); setViewMode('dashboard');
      showToast("Profile verified successfully.", "success"); setShowTour(true);
  };

  const handleCheckMaintStatus = async () => {
    setIsCheckingMaint(true);
    try { await fetchSystemSettings(appScriptUrl, true); showToast("Status updated.", "info"); } finally { setIsCheckingMaint(false); }
  };

  if (!currentUser) {
      return (
          <>
            <InstallPwaPrompt />
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
            <LoginView onLogin={handleLogin} appScriptUrl={appScriptUrl} setAppScriptUrl={setAppScriptUrl} settings={settings} />
          </>
      );
  }

  if (currentUser && currentUser.needsSetup) {
      return <OnboardingWizard user={currentUser} appScriptUrl={appScriptUrl} onComplete={handleOnboardingComplete} onLogout={handleLogout} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800 relative">
      <SubmissionOverlay 
        status={submissionStatus} 
        onClose={() => { setSubmissionStatus('idle'); setViewMode('dashboard'); }}
        onViewReport={() => lastSubmittedData && handleViewReport(lastSubmittedData)}
        aiAnalysis={aiAnalysisResult}
      />
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      {showTour && <SystemTour onComplete={() => setShowTour(false)} />}

      <AppModals
        isProfileModalOpen={isProfileModalOpen} isSolutionsOpen={isSolutionsOpen} isRequestModalOpen={isRequestModalOpen}
        isStartModalOpen={isStartModalOpen} isReportModalOpen={isReportModalOpen} currentUser={currentUser}
        settings={settings} appScriptUrl={appScriptUrl} validationLists={validationLists} hasExistingDraft={hasExistingDraft}
        pendingModule={pendingModule} activeModule={activeModule} selectedReportData={selectedReportData}
        setIsProfileModalOpen={setIsProfileModalOpen} setIsSolutionsOpen={setIsSolutionsOpen}
        setIsRequestModalOpen={setIsRequestModalOpen} setIsStartModalOpen={setIsStartModalOpen}
        setIsReportModalOpen={setIsReportModalOpen} showToast={showToast} setCurrentUser={setCurrentUser}
        handleLogout={handleLogout} handleNavigate={handleNavigate} handleRequestSubmit={handleRequestSubmit}
        handleDiscardAndStartNew={handleDiscardAndStartNew} handleResumeDraft={handleResumeDraft}
      />

      <div className="relative z-10 min-h-screen flex flex-col">
          <AppHeader 
            settings={settings} currentUser={currentUser} activeModule={activeModule} isAdmin={currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin'}
            isAtRoot={activeModule === 'overview'} isSystemLocked={isSystemLocked} lockReason={lockInfo.reason}
            subscription={subscription} notifications={notifications} isCheckingMaint={isCheckingMaint}
            onNavigateHome={() => { setActiveModule('overview'); setViewMode('dashboard'); }}
            handleMarkNotificationRead={handleMarkNotificationRead} handleDismissNotification={handleDismissNotification}
            handleClearAllNotifications={handleClearAllNotifications} handleGlobalAcknowledge={handleGlobalAcknowledge}
            handleNavigate={handleNavigate} setIsProfileModalOpen={setIsProfileModalOpen}
            handleCheckMaintStatus={handleCheckMaintStatus} setActiveModule={setActiveModule}
            setIsSolutionsOpen={setIsSolutionsOpen}
          />

          <main className="flex-1 p-4 md:p-6 w-full max-w-7xl mx-auto no-print">
              <AppContent 
                viewMode={viewMode} activeModule={activeModule} currentUser={currentUser} settings={settings}
                appScriptUrl={appScriptUrl} historyList={historyList} isLoadingHistory={isLoadingHistory}
                validationLists={validationLists} stats={stats} notifications={notifications}
                isSystemLocked={isSystemLocked} lockReason={lockInfo.reason} formInitialData={formInitialData}
                submissionStatus={submissionStatus} supportPrefill={supportPrefill}
                subscription={subscription} subHistory={subHistory}
                handleOpenInspectionFlow={handleOpenInspectionFlow} handleSaveDraft={handleSaveDraft}
                handleExitForm={handleExitForm} handleGoogleSheetSubmit={handleGoogleSheetSubmit}
                handleViewReport={handleViewReport} handleNavigate={handleNavigate}
                handleSaveSettings={handleSaveSettings} isSavingSettings={isSavingSettings}
                setSettings={setSettings} setAppScriptUrl={setAppScriptUrl} showToast={showToast}
                refreshSubscription={refreshSubscription} fetchHistory={fetchHistory}
                setIsRequestModalOpen={setIsRequestModalOpen} setSupportPrefill={setSupportPrefill}
              />
          </main>

          {!isSystemLocked && viewMode === 'dashboard' && (
              <ChatAssistant currentUser={currentUser} appScriptUrl={appScriptUrl} onNavigate={handleNavigate} />
          )}

          <AppFooter />
      </div>
    </div>
  );
};

export default App;

