// Fix: Correctly export the constant CODE_5_LIB_AND_UTILS for use in constants/scripts.ts
export const CODE_5_LIB_AND_UTILS = `/**
 * 5_LibAndUtils.gs - Helpers, Robust Email Engine & PDF Templates
 */

const ResponseBuilder = {
  success: function(data = {}) { return this.build({ status: "success", ...data }); },
  error: function(message, code = null) {
    const response = { status: "error", message: message };
    if (code) response.code = code;
    return this.build(response);
  },
  build: function(data) {
    return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
  }
};

const Validation = {
  updateFromRow: function(ss, body) {
     try {
       const row = body.row;
       const sheetName = body.sheet;
       let truck, trailer, driver, inspector, location;
       if (sheetName === 'General') {
           truck = row[2]; trailer = row[3]; inspector = row[4]; driver = row[5]; location = row[6];
       } else {
           truck = row[2]; trailer = row[3]; location = row[5]; inspector = row[7]; driver = row[8];
       }
       this.updateSingle(ss, 'Truck_Reg_No', truck);
       this.updateSingle(ss, 'Trailer_Reg_No', trailer);
       this.updateSingle(ss, 'Driver_Name', driver);
       this.updateSingle(ss, 'Inspector_Name', inspector);
       this.updateSingle(ss, 'Location', location);
     } catch (e) {}
  },
  updateSingle: function(ss, headerName, value) {
     if (!value || String(value).trim() === "") return;
     const valStr = String(value).trim();
     let vSheet = ss.getSheetByName('Validation_Data');
     if (!vSheet) {
        vSheet = ss.insertSheet('Validation_Data');
        vSheet.appendRow(['Truck_Reg_No', 'Trailer_Reg_No', 'Driver_Name', 'Inspector_Name', 'Location', 'Position']);
        vSheet.setFrozenRows(1);
     }
     const headers = vSheet.getRange(1, 1, 1, vSheet.getLastColumn()).getValues()[0];
     let colIndex = headers.indexOf(headerName) + 1;
     if (colIndex < 1) {
         colIndex = headers.length + 1;
         vSheet.getRange(1, colIndex).setValue(headerName);
     }
     const fullCol = vSheet.getRange(1, colIndex, vSheet.getMaxRows(), 1).getValues().flat().map(String);
     if (!fullCol.includes(valStr)) {
         let targetRow = 1;
         for(let i=1; i<fullCol.length; i++) {
             if(fullCol[i] === "") { targetRow = i + 1; break; }
         }
         if (targetRow === 1) targetRow = vSheet.getLastRow() + 1;
         vSheet.getRange(targetRow, colIndex).setValue(valStr);
     }
  }
};

const Logger = {
  log: function(ss, action, details) {
    let logSheet = ss.getSheetByName('System_Logs');
    if (!logSheet) {
        logSheet = ss.insertSheet('System_Logs');
        logSheet.appendRow(["Timestamp", "Action", "Details"]);
        logSheet.setFrozenRows(1);
    }
    logSheet.appendRow([new Date(), action, details]);
  }
};

const EmailHandlers = {
  sendEmailNotifications: function(ss, data, moduleName) {
    Logger.log(ss, "EMAIL_START", "Triggering for: " + moduleName);

    try {
      var recipients = [];
      var userSheet = ss.getSheetByName("Users");

      if (userSheet) {
          var users = userSheet.getDataRange().getValues();
          for (var i = 1; i < users.length; i++) {
             var userEmail = String(users[i][1]).trim(); 
             var rawPrefs = users[i][7];

             if (userEmail && userEmail.indexOf("@") > -1) {
                 try {
                     var prefs = rawPrefs ? JSON.parse(rawPrefs) : {};
                     var emailsEnabled = (prefs.emailNotifications !== false); 

                     if (emailsEnabled) {
                         var shouldSend = false;
                         if (moduleName === "General" && (prefs.notifyGeneral !== false)) shouldSend = true;
                         else if (moduleName === "Petroleum" && (prefs.notifyPetroleum !== false)) shouldSend = true;
                         else if (moduleName === "Petroleum_V2" && (prefs.notifyPetroleumV2 !== false)) shouldSend = true;
                         else if (moduleName === "Acid" && (prefs.notifyAcid !== false)) shouldSend = true;
                         else if (prefs.notifyGeneral !== false) shouldSend = true; // Safe default

                         if (shouldSend) recipients.push(userEmail);
                     }
                 } catch(e) { recipients.push(userEmail); }
             }
          }
      }

      // FALLBACK: If no registered users with alerts, send to Manager Email
      if (recipients.length === 0) {
          var settingsSheet = ss.getSheetByName("System_Settings");
          if (settingsSheet && settingsSheet.getLastRow() >= 2) {
              var mgrEmail = settingsSheet.getRange(2, 2).getValue();
              if (mgrEmail && String(mgrEmail).indexOf("@") > -1) {
                  recipients.push(String(mgrEmail).trim());
                  Logger.log(ss, "EMAIL_FALLBACK", "Using Manager Email: " + mgrEmail);
              }
          }
      }

      if (recipients.length === 0) {
          Logger.log(ss, "EMAIL_ABORT", "No valid recipients found in database.");
          return;
      }

      var row = data.row;
      var truckNo = "N/A", inspector = "N/A", rating = "N/A";

      if (moduleName === "General") {
          truckNo = row[2] || "UNIT"; inspector = row[4] || "Inspector"; rating = row[8] || "0";
      } else {
          truckNo = row[2] || "UNIT"; inspector = row[7] || "Inspector"; rating = row[9] || "0";
      }

      var statusColor = "#10b981";
      var statusText = "PASSED";
      if (rating <= 3) { statusColor = "#f59e0b"; statusText = "WARNING"; } 
      if (rating <= 2) { statusColor = "#ef4444"; statusText = "CRITICAL FAIL"; }

      var htmlBody = 
          "<div style='font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden; background-color: #ffffff;'>" +
              "<div style='background-color: #0f172a; padding: 30px; text-align: center;'>" +
                  "<h2 style='color: white; margin: 0; font-size: 18px; font-weight: 800; letter-spacing: 2px; text-transform: uppercase;'>Safety Alert System</h2>" +
              "</div>" +
              "<div style='padding: 30px; color: #1e293b;'>" +
                  "<p style='margin-top: 0; font-size: 14px;'>A new <strong>" + moduleName + "</strong> audit has been synchronized with the fleet registry.</p>" +
                  "<div style='background-color: #f8fafc; padding: 25px; border-radius: 12px; border: 1px solid #f1f5f9; margin: 25px 0;'>" +
                      "<table style='width: 100%; border-collapse: collapse;'>" +
                          "<tr>" +
                              "<td style='padding: 8px 0; color: #94a3b8; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px;'>Asset Registration</td>" +
                              "<td style='padding: 8px 0; color: #0f172a; font-size: 15px; font-weight: 800; text-align: right;'>" + truckNo + "</td>" +
                          "</tr>" +
                          "<tr>" +
                              "<td style='padding: 8px 0; color: #94a3b8; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px;'>Auditor</td>" +
                              "<td style='padding: 8px 0; color: #0f172a; font-size: 15px; font-weight: 600; text-align: right;'>" + inspector + "</td>" +
                          "</tr>" +
                          "<tr>" +
                              "<td style='padding: 8px 0; color: #94a3b8; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px;'>Safety Rating</td>" +
                              "<td style='padding: 8px 0; text-align: right;'>" +
                                  "<span style='color: " + statusColor + "; font-weight: 900; font-size: 16px;'>" + statusText + " (" + rating + "/5)</span>" +
                              "</td>" +
                          "</tr>" +
                      "</table>" +
                  "</div>" +
                  "<p style='font-size: 13px; line-height: 1.6; color: #64748b;'>An official digital transcript of this audit is attached for your records. Please review critical faults immediately to mitigate fleet risks.</p>" +
                  "<div style='margin-top: 30px; padding-top: 20px; border-top: 1px solid #f1f5f9; text-align: center;'>" +
                      "<p style='font-size: 10px; color: #cbd5e1; text-transform: uppercase; letter-spacing: 1px; margin: 0;'>Automated Payload: No Reply Required</p>" +
                  "</div>" +
              "</div>" +
          "</div>";

      var blobs = [];
      if (data.reportData) {
          try {
              var reportHtml = PDFGenerator.create(data.reportData);
              var pdfBlob = Utilities.newBlob(reportHtml, 'text/html')
                  .getAs('application/pdf')
                  .setName(String(truckNo).replace(/\\s/g, '_') + '_' + moduleName + '_Report.pdf');
              blobs.push(pdfBlob);
          } catch (e) { Logger.log(ss, "PDF_GEN_FAIL", e.toString()); }
      }

      var subject = "Audit Report: " + truckNo + " [" + statusText + "]";
      var emailOptions = {
          htmlBody: htmlBody,
          name: "SafetyCheck Alerts", 
          attachments: blobs
      };

      if (recipients.length > 1) {
          emailOptions.bcc = recipients.slice(1).join(",");
      }

      GmailApp.sendEmail(recipients[0], subject, "HTML Required", emailOptions);
      Logger.log(ss, "EMAIL_DISPATCHED", "To: " + recipients[0] + " + " + (recipients.length-1) + " others.");

    } catch (err) {
        Logger.log(ss, "EMAIL_SYSTEM_FATAL", err.toString());
    }
  },

  sendInvitation: function(email, role, orgName) {
    const subject = "Access Invitation: " + orgName;
    const htmlBody = '<div style="font-family: Arial, sans-serif; padding: 32px; border: 1px solid #f1f5f9; border-radius: 20px; max-width: 600px; color: #0f172a; background: #ffffff;">' +
      '<h2 style="color: #4f46e5; margin-bottom: 20px; font-size: 22px; font-weight: 800; letter-spacing: -0.02em;">Welcome to the Portal</h2>' +
      '<p style="font-size: 15px; line-height: 1.6; color: #475569;">You have been enrolled as a fleet auditor for <strong>' + orgName + '</strong>.</p>' +
      '<div style="background: #f8fafc; padding: 24px; border-radius: 16px; margin: 24px 0; border: 1px solid #f1f5f9;">' +
        '<p style="margin: 0 0 10px 0; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 1px;">Access Credentials</p>' +
        '<p style="margin: 0; font-size: 14px; font-weight: 600;">Role: ' + role + '</p>' +
        '<p style="margin: 4px 0 0 0; font-size: 14px; font-weight: 600;">ID: ' + email + '</p>' +
      '</div>' +
      '<p style="font-size: 14px; line-height: 1.6; color: #64748b;">Sign in with your email. Leave the password blank for your initial setup.</p>' +
    '</div>';

    try {
      MailApp.sendEmail(email, subject, "Invitation", { htmlBody: htmlBody });
    } catch (e) {}
  }
};

const PDFGenerator = {
  create: function(data) {
    if (data.title && (data.title.indexOf('General') > -1 || data.title.indexOf('GENERAL') > -1)) {
       return this.createGeneralReport(data);
    }
    if (data.title && data.title.indexOf('Petroleum Tanker Inspection V2') > -1) {
       return this.createPetroleumV2Report(data);
    }
    if (data.title && data.title.indexOf('Petroleum Tanker Inspection') > -1) {
       return this.createPetroleumReport(data);
    }
    if (data.title && data.title.indexOf('Acid Tanker Inspection') > -1) {
       return this.createAcidReport(data);
    }
    return this.createGenericReport(data);
  },

  createAcidReport: function(data) {
      var dateStr = new Date(data.timestamp).toLocaleString('en-GB');
      var itemsHtml = "";
      var currentCategory = "";
      (data.items || []).forEach(function(item) {
          var headerText = item.category;
          if (headerText !== currentCategory) {
              currentCategory = headerText;
              itemsHtml += "<tr><td colspan='3' style='background-color:#f1f5f9; font-weight:bold; border:1px solid #cbd5e1; padding:8px; font-size:10px; text-transform:uppercase;'>" + currentCategory + "</td></tr>";
          }
          var statusStyle = item.status === 'Bad' ? "color:#ef4444;font-weight:800;" : "";
          itemsHtml += "<tr>" +
              "<td style='border:1px solid #e2e8f0; padding:6px; text-align:center; color:#94a3b8;'>•</td>" +
              "<td style='border:1px solid #e2e8f0; padding:6px 10px; font-size:11px;'>" + item.label + "</td>" +
              "<td style='border:1px solid #e2e8f0; padding:6px 10px; font-size:11px; " + statusStyle + "'>" + (item.status || "") + "</td>" +
              "</tr>";
      });
      return "<html><body style='font-family: sans-serif;'>" +
          "<h2 style='text-align:center; color:#0f172a; text-transform:uppercase;'>Acid Tanker Checklist</h2>" +
          "<div style='margin-bottom:20px; font-size:12px; border-bottom:1px solid #eee; padding-bottom:10px;'><b>Asset:</b> " + data.truckNo + " | <b>Trailer:</b> " + data.trailerNo + " | <b>Timestamp:</b> " + dateStr + "</div>" +
          "<table style='width:100%; border-collapse:collapse;'>" + itemsHtml + "</table>" +
          "<div style='margin-top:30px; padding:15px; background:#f8fafc; border-radius:8px;'><b>Inspector Comments:</b><br/>" + data.remarks + "</div>" +
          "</body></html>";
  },

  createPetroleumV2Report: function(data) {
      var dateStr = new Date(data.timestamp).toLocaleString('en-GB');
      var itemsHtml = "";
      var currentCategory = "";
      (data.items || []).forEach(function(item) {
          if (item.category !== currentCategory) {
              currentCategory = item.category;
              itemsHtml += "<tr><td colspan='3' style='background-color:#1e293b; color:white; font-weight:bold; border:1px solid #000; padding:8px; text-align:center; text-transform:uppercase; font-size:10px;'>" + currentCategory + "</td></tr>";
          }
          itemsHtml += "<tr>" +
              "<td style='border:1px solid #ccc; padding:6px 10px; width:70%; font-size:11px;'>" + item.label + "</td>" +
              "<td style='border:1px solid #ccc; padding:6px; text-align:center; font-weight:bold;'>" + (item.status === 'Good' ? 'YES' : '-') + "</td>" +
              "<td style='border:1px solid #ccc; padding:6px; text-align:center; color:red; font-weight:bold;'>" + (item.status === 'Bad' ? 'NO' : '-') + "</td>" +
              "</tr>";
      });
      return "<html><body style='font-family:Helvetica; padding:30px;'>" +
          "<h1 style='text-align:center; color:#0f172a; font-size:24px;'>PETROLEUM V2 AUDIT</h1>" +
          "<div style='border:1px solid #e2e8f0; padding:15px; margin-bottom:20px; border-radius:8px; background:#f8fafc;'><b>Asset Identification:</b> " + data.truckNo + " (" + data.trailerNo + ") <br/><b>Sync Time:</b> " + dateStr + "</div>" +
          "<table style='width:100%; border-collapse:collapse;'>" + itemsHtml + "</table>" +
          "</body></html>";
  },

  createGeneralReport: function(data) {
      var dateStr = new Date(data.timestamp).toLocaleString('en-GB');
      var itemsHtml = "";
      (data.items || []).forEach(function(item) {
          itemsHtml += "<tr><td style='border-bottom:1px solid #f1f5f9; padding:10px; color:#475569; font-size:11px;'>" + item.label + "</td><td style='border-bottom:1px solid #f1f5f9; padding:10px; text-align:right; font-weight:bold; color:#0f172a; font-size:11px;'>" + item.status + "</td></tr>";
      });
      return "<html><body style='font-family:Arial; padding:40px; color:#1e293b;'>" +
          "<div style='text-align:center; border-bottom:4px solid #0f172a; padding-bottom:20px; margin-bottom:30px;'>" +
          "<h2 style='margin:0; letter-spacing:1px;'>VEHICLE INSPECTION LOG</h2><p style='color:#94a3b8; font-size:12px; margin-top:5px;'>" + dateStr + "</p></div>" +
          "<div style='margin-bottom:30px; font-size:13px;'><b>Asset:</b> " + data.truckNo + " <br/><b>Auditor:</b> " + data.inspectedBy + "</div>" +
          "<table style='width:100%; border-collapse:collapse;'>" + itemsHtml + "</table>" +
          "<div style='margin-top:40px; background:#f8fafc; padding:20px; border-radius:12px; border:1px solid #f1f5f9;'>" +
          "<b>Operational Status:</b> " + (data.safeToLoad === 'Yes' ? 'CLEAR FOR DISPATCH' : 'GROUNDED') + "<br/><b>Remarks:</b> " + data.remarks + "</div>" +
          "</body></html>";
  },

  createGenericReport: function(data) {
    return "<html><body><h1>" + data.title + "</h1><p>Date: " + data.timestamp + "</p></body></html>";
  }
};\`;

/**
 * 1_Controller.gs
 * Main entry points and request routing.
 */

export const CODE_1_CONTROLLER = `/**
 * 1_Controller.gs - Main entry points and request routing.
 */

function doPost(e) {
  const lock = LockService.getScriptLock();
  // Professional 30s lock to prevent race conditions during multi-user submissions
  lock.tryLock(30000); 

  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const body = e.postData ? JSON.parse(e.postData.contents) : {};
    return routeRequest(ss, body);
  } catch (err) {
    return ResponseBuilder.error("System Exception: " + err.toString());
  } finally {
    lock.releaseLock();
  }
}

function doGet(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  return DataHandlers.handleGetRequest(ss);
}

function routeRequest(ss, body) {
  const action = body.action;
  const routes = {
    'login': () => AuthHandlers.handleLogin(ss, body),
    'register_user': () => AuthHandlers.handleRegisterUser(ss, body),
    'get_users': () => AuthHandlers.handleGetUsers(ss),
    'delete_user': () => AuthHandlers.handleDeleteUser(ss, body),
    'update_user': () => AuthHandlers.handleUpdateUser(ss, body),
    'heartbeat': () => AuthHandlers.handleHeartbeat(ss, body),
    'mark_read': () => AuthHandlers.handleMarkRead(ss, body),
    'manage_fleet': () => SystemHandlers.handleManageFleet(ss, body),
    'bulk_manage_fleet': () => SystemHandlers.handleBulkManageFleet(ss, body),
    'acknowledge_issue': () => SystemHandlers.handleAcknowledgeIssue(ss, body),
    'request_inspection': () => SystemHandlers.handleRequestInspection(ss, body),
    'get_acknowledgements': () => SystemHandlers.handleGetAcknowledgements(ss),
    'mark_notification_read': () => SystemHandlers.handleMarkNotificationRead(ss, body),
    'update_settings': () => SystemHandlers.handleUpdateSettings(ss, body),
    'broadcast': () => SystemHandlers.handleBroadcast(ss, body),
    'acknowledge_notification': () => SystemHandlers.handleAcknowledgeNotification(ss, body),
    'check_subscription': () => SubscriptionHandlers.handleCheckSubscription(ss),
    'extend_subscription': () => SubscriptionHandlers.handleExtendSubscription(ss, body),
    'submit_support_ticket': () => SupportHandlers.handleSubmitSupport(ss, body),
    'get_tickets': () => SupportHandlers.handleGetTickets(ss, body),
    'update_ticket': () => SupportHandlers.handleUpdateTicket(ss, body),
    'initiate_mobile_payment': () => PaymentHandlers.handleMobileMoney(ss, body)
  };

  if (!action || action === 'create' || !routes[action]) {
    return DataHandlers.handleDataSubmission(ss, body);
  }
  return routes[action]();
}`;

/**
 * 2_AuthAndAdmin.gs
 * Handles authentication and staff management.
 */

export const CODE_2_AUTH_AND_ADMIN = `/**
 * 2_AuthAndAdmin.gs - Authentication & User Management
 */

const AuthHandlers = {
  handleLogin: function(ss, body) {
    let userSheet = ss.getSheetByName('Users');
    if (!userSheet) return ResponseBuilder.error("Database Configuration Error: 'Users' sheet not found.");
    const data = userSheet.getDataRange().getValues();
    const username = body.username.toLowerCase().trim();

    for (let i = 1; i < data.length; i++) {
        const storedUser = String(data[i][1]).toLowerCase().trim();
        const storedPass = String(data[i][2]);
        const storedName = String(data[i][3]);
        const userRole = data[i][4];
        const userId = data[i][0];

        if (storedUser === username) {
            const passwordMatch = (storedPass === body.password);
            const isNewUserInvite = (storedName === "" && storedPass === "" && body.password === "");

            if (passwordMatch || isNewUserInvite) {
                const isEnabled = data[i][8] === undefined || data[i][8] === "" || String(data[i][8]).toUpperCase() === "TRUE";
                if (!isEnabled) return ResponseBuilder.error("Account Access Disabled.", "ACCOUNT_DISABLED");

                userSheet.getRange(i + 1, 10).setValue(new Date().toISOString());
                let prefs = {};
                try { if (data[i][7]) prefs = JSON.parse(data[i][7]); } catch(e) {}

                return ResponseBuilder.success({ 
                  user: { id: userId, username: storedUser, name: storedName, role: String(userRole).trim(), position: data[i][5] || '', preferences: prefs, isActive: isEnabled } 
                });
            }
        }
    }
    return ResponseBuilder.error("Invalid credentials.", "INVALID_CREDENTIALS");
  },

  handleHeartbeat: function(ss, body) {
    let msgSheet = ss.getSheetByName('Messages');
    if (!msgSheet) return ResponseBuilder.error("Messages sheet missing");
    const username = body.username.toLowerCase();
    const statusType = body.isTyping ? "Typing" : "Presence";
    const now = new Date().toISOString();

    const data = msgSheet.getDataRange().getValues();
    let foundIndex = -1;
    for (let i = data.length - 1; i >= Math.max(1, data.length - 200); i--) {
      if (String(data[i][1]).toLowerCase() === username && data[i][4] === "HB") {
        foundIndex = i; break;
      }
    }

    if (foundIndex !== -1) {
      msgSheet.getRange(foundIndex + 1, 6).setValue(now);
      msgSheet.getRange(foundIndex + 1, 7).setValue(statusType);
    } else {
      msgSheet.appendRow(["HB-" + Date.now(), body.username, body.name || "User", "ALL", "HB", now, statusType]);
    }
    return ResponseBuilder.success();
  },

  handleRegisterUser: function(ss, body) {
    let userSheet = ss.getSheetByName('Users');
    if (!userSheet) {
        userSheet = ss.insertSheet('Users');
        userSheet.appendRow(["ID", "Username", "Password", "Name", "Role", "Position", "Registered_At", "Preferences", "Enabled", "Last_Seen", "Is_Typing"]);
        userSheet.setFrozenRows(1);
    }
    const newUsername = String(body.username).trim().toLowerCase();
    const id = "USR-" + Date.now();
    const defaultPrefs = JSON.stringify({ emailNotifications: true, notifyGeneral: true, notifyPetroleum: true, notifyAcid: true });
    userSheet.appendRow([id, newUsername, body.password || "", body.name || "", String(body.role).trim(), body.position || "", new Date().toISOString(), defaultPrefs, "TRUE", "", "FALSE"]);

    if (typeof EmailHandlers !== 'undefined' && EmailHandlers.sendInvitation) {
      EmailHandlers.sendInvitation(newUsername, body.role, "Fleet Portal");
    }
    return ResponseBuilder.success({ message: "User registered." });
  },

  handleUpdateUser: function(ss, body) {
    let sheet = ss.getSheetByName('Users');
    if (!sheet) return ResponseBuilder.error("Users sheet missing");
    const data = sheet.getDataRange().getValues();
    for (let i = 1; i < data.length; i++) {
      if (data[i][1].toLowerCase() === (body.originalUsername || body.username).toLowerCase()) {
        if (body.username) sheet.getRange(i + 1, 2).setValue(body.username.toLowerCase());
        if (body.password) sheet.getRange(i + 1, 3).setValue(body.password);
        if (body.name) sheet.getRange(i + 1, 4).setValue(body.name);
        if (body.role) sheet.getRange(i + 1, 5).setValue(String(body.role).trim());
        if (body.position !== undefined) sheet.getRange(i + 1, 6).setValue(body.position);
        if (body.isActive !== undefined) sheet.getRange(i + 1, 9).setValue(body.isActive ? "TRUE" : "FALSE");
        if (body.preferences) sheet.getRange(i + 1, 8).setValue(JSON.stringify(body.preferences));
        return ResponseBuilder.success();
      }
    }
    return ResponseBuilder.error("User not found");
  },

  handleGetUsers: function(ss) {
    let userSheet = ss.getSheetByName('Users');
    if (!userSheet) return ResponseBuilder.success({ users: [] });
    const userData = userSheet.getDataRange().getValues();
    const users = userData.slice(1).map(r => ({ 
      id: r[0], username: r[1], name: r[3], role: r[4], position: r[5], lastLogin: r[6],
      isActive: r[8] === undefined || r[8] === "" || String(r[8]).toUpperCase() === "TRUE"
    }));
    return ResponseBuilder.success({ users });
  }
};`;

/**
 * 3_CoreOperations.gs
 * Handles data flow, fleet assets, and system configuration.
 */

export const CODE_3_CORE_OPERATIONS = `/**
 * 3_CoreOperations.gs - Core Data Flow & Systems
 */

const DataHandlers = {
  handleDataSubmission: function(ss, body) {
    const sheetName = body.sheet;
    const rowData = body.row;
    let sheet = ss.getSheetByName(sheetName);

    if (!sheet) return ResponseBuilder.error("Target registry '" + sheetName + "' not found.");

    const safeRow = rowData.map(r => (r === null || r === undefined) ? "" : String(r));
    sheet.appendRow(safeRow);

    // Track original request completion
    if (body.requestId) {
        const reqSheet = ss.getSheetByName('Inspection_Requests');
        if (reqSheet) {
            const reqData = reqSheet.getDataRange().getValues();
            for (let i = 1; i < reqData.length; i++) {
                if (String(reqData[i][0]) === String(body.requestId)) {
                    reqSheet.getRange(i + 1, 10).setValue('Completed');
                    break;
                }
            }
        }
    }

    // DISPATCH EMAIL NOTIFICATIONS
    if (typeof EmailHandlers !== 'undefined') {
       EmailHandlers.sendEmailNotifications(ss, body, sheetName);
    }

    // UPDATE AUTO-SUGGESTION REGISTRY
    if (typeof Validation !== 'undefined') {
       Validation.updateFromRow(ss, body);
    }

    return ResponseBuilder.success({ sheet: sheetName });
  },

  handleGetRequest: function(ss) {
    const sheets = ss.getSheets();
    const data = {};
    sheets.forEach(sheet => {
      const name = sheet.getName();
      if (name === 'Users' || name === 'System_Logs') return;

      const lastRow = sheet.getLastRow();
      if (lastRow === 0) {
          data[name] = [];
          return;
      }

      if (name === 'Validation_Data') {
         if (lastRow > 1) {
            const range = sheet.getRange(2, 1, lastRow - 1, sheet.getLastColumn());
            const values = range.getValues();
            const columns = {};
            const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
            headers.forEach((h, colIndex) => {
               columns[h] = [...new Set(values.map(row => row[colIndex]).filter(c => c !== ""))]; 
            });
            data[name] = columns;
         } else { data[name] = {}; }
      } else if (name === 'System_Settings') {
          data[name] = sheet.getDataRange().getValues();
      } else if (name === 'Subscription_Data') {
          const values = sheet.getDataRange().getValues();
          if (values.length > 1) {
            const lastRow = values[values.length - 1];
            data[name] = { 
                current: { status: lastRow[0], plan: lastRow[1], expiryDate: lastRow[2], processedBy: lastRow[3] },
                history: values.slice(1).map(r => ({ status: r[0], plan: r[1], expiryDate: r[2], processedBy: r[3], timestamp: r[4] }))
            };
          } else { data[name] = { current: { status: "Expired" }, history: [] }; }
      } else {
         const startRow = Math.max(1, lastRow - 300);
         const values = sheet.getRange(startRow, 1, lastRow - startRow + 1, sheet.getLastColumn()).getValues();
         if (startRow > 1) values.unshift(sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0]);
         data[name] = values;
      }
    });
    return ResponseBuilder.build(data);
  }
};

const SystemHandlers = {
  handleBroadcast: function(ss, body) {
    const sheet = ss.getSheetByName('Messages');
    if (!sheet) return ResponseBuilder.error("Messages system offline.");
    sheet.appendRow([Date.now(), "SYSTEM", "Automated Console", "ALL", "[BROADCAST]: " + body.message, new Date().toISOString(), "Sent"]);
    return ResponseBuilder.success();
  },

  handleRequestInspection: function(ss, body) {
    let sheet = ss.getSheetByName('Inspection_Requests');
    if (!sheet) {
        sheet = ss.insertSheet('Inspection_Requests');
        sheet.appendRow(['ID', 'Requester', 'Role', 'Truck', 'Trailer', 'Type', 'Reason', 'Priority', 'AssignedTo', 'Status', 'Timestamp']);
    }
    const requestId = "REQ-" + Date.now();
    sheet.appendRow([requestId, body.requester, body.role, body.truckNo, body.trailerNo || "", body.type, body.reason, body.priority, body.assignedInspector || "Unassigned", "Pending", new Date().toISOString()]);
    return ResponseBuilder.success({ requestId });
  },

  handleUpdateSettings: function(ss, body) {
    let sheet = ss.getSheetByName('System_Settings');
    if (!sheet) {
        sheet = ss.insertSheet('System_Settings');
        sheet.appendRow(['Company_Name', 'Manager_Email', 'Last_Updated', 'Updated_By', 'Maintenance_Mode', 'Logo_Data', 'Mobile_Link', 'Web_Link', 'Maintenance_Msg', 'Payment_Key']);
    }
    const row = [body.companyName, body.managerEmail, new Date(), "Admin", body.maintenanceMode ? "TRUE" : "FALSE", body.companyLogo, body.mobileApkLink, body.webAppUrl, body.maintenanceMessage, body.flutterwaveSecretKey];
    if (sheet.getLastRow() < 2) sheet.appendRow(row);
    else sheet.getRange(2, 1, 1, row.length).setValues([row]);
    return ResponseBuilder.success();
  }
};

const SubscriptionHandlers = {
  handleCheckSubscription: function(ss) {
    const sheet = ss.getSheetByName('Subscription_Data');
    if (!sheet || sheet.getLastRow() < 2) return ResponseBuilder.success({ status: "Expired" });
    const lastRow = sheet.getRange(sheet.getLastRow(), 1, 1, 4).getValues()[0];
    return ResponseBuilder.success({ status: lastRow[0], plan: lastRow[1], expiryDate: lastRow[2] });
  },
  handleExtendSubscription: function(ss, body) {
    let sheet = ss.getSheetByName('Subscription_Data');
    if (!sheet) {
      sheet = ss.insertSheet('Subscription_Data');
      sheet.appendRow(['Status', 'Plan', 'ExpiryDate', 'ProcessedBy', 'Timestamp']);
    }
    sheet.appendRow([body.status || "Active", body.plan || "Standard", body.expiryDate, "Admin", new Date().toISOString()]);
    return ResponseBuilder.success();
  }
};

const PaymentHandlers = {
  handleMobileMoney: function(ss, body) {
    // Placeholder for Flutterwave / Zambian Gateway logic
    return ResponseBuilder.success({ message: "Mock Payment: Payment prompt sent to " + body.phoneNumber });
  }
};`;

/**
 * 4_SupportModule.gs
 * Handles communication and support ticket tracking.
 */

export const CODE_4_SUPPORT_MODULE = `/**
 * 4_SupportModule.gs - Support Ticketing System
 */

const SupportHandlers = {
  handleSubmitSupport: function(ss, body) {
    let sheet = ss.getSheetByName('Support_Tickets');
    if (!sheet) {
        sheet = ss.insertSheet('Support_Tickets');
        sheet.appendRow(["ID", "Type", "Subject", "Description", "Priority", "User", "Email", "Role", "Timestamp", "Status", "Comments", "AssignedTo", "Attachment"]);
    }
    const id = "TKT-" + Math.floor(Math.random()*90000 + 10000);
    sheet.appendRow([id, body.type, body.subject, body.description, body.priority, body.user, body.email, body.role, new Date().toISOString(), "Open", "[]", "", ""]);

    // Dispatch system alert
    let notifSheet = ss.getSheetByName('SystemNotification');
    if (notifSheet) {
        notifSheet.appendRow(["NOTIF-" + Date.now(), "Admin", "info", "New Support Ticket: " + id, new Date().toISOString(), "FALSE", "support"]);
    }

    return ResponseBuilder.success({ ticketId: id });
  },

  handleGetTickets: function(ss, body) {
    const sheet = ss.getSheetByName('Support_Tickets');
    if (!sheet) return ResponseBuilder.success({ tickets: [] });
    const data = sheet.getDataRange().getValues();
    const userRole = (body.role || "").toLowerCase();
    const userEmail = (body.email || "").toLowerCase();
    const isAdmin = userRole === 'admin' || userRole === 'superadmin';

    const tickets = data.slice(1).filter(r => {
        if (isAdmin) return true;
        return String(r[6]).toLowerCase() === userEmail;
    }).map(r => ({
        ticketId: r[0], type: r[1], subject: r[2], description: r[3],
        priority: r[4], user: r[5], email: r[6], role: r[7],
        timestamp: r[8], status: r[9], comments: JSON.parse(r[10] || "[]"),
        assignedTo: r[11], attachment: r[12]
    })).reverse();

    return ResponseBuilder.success({ tickets });
  },

  handleUpdateTicket: function(ss, body) {
    const sheet = ss.getSheetByName('Support_Tickets');
    if (!sheet) return ResponseBuilder.error("Sheet missing.");
    const data = sheet.getDataRange().getValues();
    for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]) === String(body.ticketId)) {
            const rowIndex = i + 1;
            if (body.status) sheet.getRange(rowIndex, 10).setValue(body.status);
            if (body.comment) {
                const current = JSON.parse(sheet.getRange(rowIndex, 11).getValue() || "[]");
                current.push(body.comment);
                sheet.getRange(rowIndex, 11).setValue(JSON.stringify(current));
            }
            return ResponseBuilder.success();
        }
    }
    return ResponseBuilder.error("Ticket not found.");
  }
};`;

