          "<div style='margin-top:30px; padding:15px; background:#f8fafc; border-radius:8px;'><b>Inspector Comments:</b><br/>" + data.remarks + "</div>" +
          "</body></html>";
  },

  createPetroleumV2Report: function(data) {
      var dateStr = new Date(data.timestamp).toLocaleString('en-GB');
      var itemsHtml = "";
      var currentCategory = "";
      (data.items || []).forEach(function(item) {
          if (item.category !== currentCategory) {
              currentCategory = item.category;
              itemsHtml += "<tr><td colspan='3' style='background-color:#1e293b; color:white; font-weight:bold; border:1px solid #000; padding:8px; text-align:center; text-transform:uppercase; font-size:10px;'>" + currentCategory + "</td></tr>";
          }
          itemsHtml += "<tr>" +
              "<td style='border:1px solid #ccc; padding:6px 10px; width:70%; font-size:11px;'>" + item.label + "</td>" +
              "<td style='border:1px solid #ccc; padding:6px; text-align:center; font-weight:bold;'>" + (item.status === 'Good' ? 'YES' : '-') + "</td>" +
              "<td style='border:1px solid #ccc; padding:6px; text-align:center; color:red; font-weight:bold;'>" + (item.status === 'Bad' ? 'NO' : '-') + "</td>" +
              "</tr>";
      });
      return "<html><body style='font-family:Helvetica; padding:30px;'>" +
          "<h1 style='text-align:center; color:#0f172a; font-size:24px;'>PETROLEUM V2 AUDIT</h1>" +
          "<div style='border:1px solid #e2e8f0; padding:15px; margin-bottom:20px; border-radius:8px; background:#f8fafc;'><b>Asset Identification:</b> " + data.truckNo + " (" + data.trailerNo + ") <br/><b>Sync Time:</b> " + dateStr + "</div>" +
          "<table style='width:100%; border-collapse:collapse;'>" + itemsHtml + "</table>" +
          "</body></html>";
  },

  createGeneralReport: function(data) {
      var dateStr = new Date(data.timestamp).toLocaleString('en-GB');
      var itemsHtml = "";
      (data.items || []).forEach(function(item) {
          itemsHtml += "<tr><td style='border-bottom:1px solid #f1f5f9; padding:10px; color:#475569; font-size:11px;'>" + item.label + "</td><td style='border-bottom:1px solid #f1f5f9; padding:10px; text-align:right; font-weight:bold; color:#0f172a; font-size:11px;'>" + item.status + "</td></tr>";
      });
      return "<html><body style='font-family:Arial; padding:40px; color:#1e293b;'>" +
          "<div style='text-align:center; border-bottom:4px solid #0f172a; padding-bottom:20px; margin-bottom:30px;'>" +
          "<h2 style='margin:0; letter-spacing:1px;'>VEHICLE INSPECTION LOG</h2><p style='color:#94a3b8; font-size:12px; margin-top:5px;'>" + dateStr + "</p></div>" +
          "<div style='margin-bottom:30px; font-size:13px;'><b>Asset:</b> " + data.truckNo + " <br/><b>Auditor:</b> " + data.inspectedBy + "</div>" +
          "<table style='width:100%; border-collapse:collapse;'>" + itemsHtml + "</table>" +
          "<div style='margin-top:40px; background:#f8fafc; padding:20px; border-radius:12px; border:1px solid #f1f5f9;'>" +
          "<b>Operational Status:</b> " + (data.safeToLoad === 'Yes' ? 'CLEAR FOR DISPATCH' : 'GROUNDED') + "<br/><b>Remarks:</b> " + data.remarks + "</div>" +
          "</body></html>";
  },

  createGenericReport: function(data) {
    return "<html><body><h1>" + data.title + "</h1><p>Date: " + data.timestamp + "</p></body></html>";
  }
};`

import React from 'react';
import { User, SystemSettings, InspectionData, ValidationLists } from '../../types';

// UI Components
import ProfileModal from '../ui/ProfileModal';
import SolutionsDrawer from '../ui/SolutionsDrawer';
import RequestInspectionModal from '../ui/RequestInspectionModal';
import InspectionStartModal from '../ui/InspectionStartModal';
import ReportViewerModal from '../ui/ReportViewerModal';

// Report Components
import PrintableGeneralReport from '../reports/PrintableGeneralReport';
import PrintablePetroleumReport from '../reports/PrintablePetroleumReport';
import PrintablePetroleumV2Report from '../reports/PrintablePetroleumV2Report';
import PrintableAcidReport from '../reports/PrintableAcidReport';

interface AppModalsProps {
    isProfileModalOpen: boolean;
    isSolutionsOpen: boolean;
    isRequestModalOpen: boolean;
    isStartModalOpen: boolean;
    isReportModalOpen: boolean;
    currentUser: User;
    settings: SystemSettings;
    appScriptUrl: string;
    validationLists: ValidationLists;
    hasExistingDraft: boolean;
    pendingModule: string | null;
    activeModule: string;
    selectedReportData: InspectionData | null;

    setIsProfileModalOpen: (open: boolean) => void;
    setIsSolutionsOpen: (open: boolean) => void;
    setIsRequestModalOpen: (open: boolean) => void;
    setIsStartModalOpen: (open: boolean) => void;
    setIsReportModalOpen: (open: boolean) => void;

    showToast: any;
    setCurrentUser: (user: User) => void;
    handleLogout: () => void;
    handleNavigate: (module: string) => void;
    handleRequestSubmit: (data: any) => void;
    handleDiscardAndStartNew: () => void;
    handleResumeDraft: () => void;
}

const AppModals: React.FC<AppModalsProps> = ({
    isProfileModalOpen, isSolutionsOpen, isRequestModalOpen, isStartModalOpen, isReportModalOpen,
    currentUser, settings, appScriptUrl, validationLists, hasExistingDraft, pendingModule, activeModule, selectedReportData,
    setIsProfileModalOpen, setIsSolutionsOpen, setIsRequestModalOpen, setIsStartModalOpen, setIsReportModalOpen,
    showToast, setCurrentUser, handleLogout, handleNavigate, handleRequestSubmit, handleDiscardAndStartNew, handleResumeDraft
}) => {

    // Robust template detection based on data payload
    const renderReportTemplate = (data: InspectionData) => {
        if (data.petro_1 !== undefined) {
            return <PrintablePetroleumReport data={data} settings={settings} />;
        }
        if (data.petro2_1 !== undefined) {
            return <PrintablePetroleumV2Report data={data} settings={settings} />;
        }
        if (data.acid_1 !== undefined) {
            return <PrintableAcidReport data={data} settings={settings} />;
        }
        return <PrintableGeneralReport data={data} settings={settings} />;
    };

    const getReportTitle = (data: InspectionData) => {
        if (data.petro_1 !== undefined) return 'Petroleum_V1_Report';
        if (data.petro2_1 !== undefined) return 'Petroleum_V2_Report';
        if (data.acid_1 !== undefined) return 'Acid_Tanker_Report';
        return 'General_Vehicle_Report';
    };

    return (
        <>
            {isProfileModalOpen && (
                <ProfileModal 
                    user={currentUser} 
                    settings={settings} 
                    appScriptUrl={appScriptUrl} 
                    onClose={() => setIsProfileModalOpen(false)} 
                    showToast={showToast} 
                    onUpdateSuccess={(u) => setCurrentUser(u)} 
                    onLogout={() => { setIsProfileModalOpen(false); handleLogout(); }} 
                />
            )}

            {isSolutionsOpen && (
                <SolutionsDrawer isOpen={isSolutionsOpen} onClose={() => setIsSolutionsOpen(false)} onAction={handleNavigate} />
            )}

            <RequestInspectionModal 
                isOpen={isRequestModalOpen} 
                onClose={() => setIsRequestModalOpen(false)} 
                onSubmit={handleRequestSubmit} 
                validationLists={validationLists} 
                currentUserRole={currentUser.role} 
            />

            <InspectionStartModal 
                isOpen={isStartModalOpen} 
                onClose={() => setIsStartModalOpen(false)} 
                onStartNew={handleDiscardAndStartNew} 
                onResume={handleResumeDraft} 
                hasDraft={hasExistingDraft} 
                moduleName={pendingModule || ''} 
            />

            {isReportModalOpen && selectedReportData && (
                <ReportViewerModal 
                    onClose={() => setIsReportModalOpen(false)} 
                    onPrint={() => window.print()} 
                    title={`${getReportTitle(selectedReportData)}_${selectedReportData.truckNo || 'Unit'}`}
                >
                    {renderReportTemplate(selectedReportData)}
                </ReportViewerModal>
            )}
        </>
    );
};

export default AppModals;

