        setIsGenerating(true);

        try {
            const filename = `${title.replace(/[^a-zA-Z0-9]/g, '_')}_${new Date().getTime()}.pdf`;

            // Standard A4 dimensions in pixels at 96 DPI is ~794px. 
            // We use a fixed width for the capture to avoid UI scaling interference.
            const opt = {
                margin: [0, 0, 0, 0],
                filename: filename,
                image: { type: 'jpeg', quality: 0.98 },
                html2canvas: { 
