                    windowWidth: 800 // Forces the renderer to think it's on a standard desktop width
                },
                jsPDF: { 
                    unit: 'mm', 
                    format: 'a4', 
                    orientation: 'portrait',
                    compress: true
                }
            };

            const html2pdf = (window as any).html2pdf;
            if (!html2pdf) {
                throw new Error("PDF library not loaded");
            }

            // Execute the PDF generation and download
            await html2pdf().set(opt).from(element).save();

        } catch (err) {
            console.error("PDF Generation Error:", err);
            alert("Digital export encountered a delay. Please try again or use the 'Print' button.");
        } finally {
