                            onClick={handleDownload}
                            disabled={isGenerating}
                            className="px-5 py-2.5 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-lg flex items-center gap-2 transition-all active:scale-95 disabled:bg-slate-400 disabled:cursor-wait"
