    title: string;
}

const ReportViewerModal: React.FC<ReportViewerModalProps> = ({ 
    onClose, 
    children, 
    title 
}) => {
    const [showMenu, setShowMenu] = useState(false);
    const menuRef = useRef<HTMLDivElement>(null);

    // Close menu when clicking outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setShowMenu(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleDownloadPdf = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();

        const element = document.getElementById('printable-report-content');
        if (!element) return;

        setShowMenu(false);

        // Professional configuration for high-resolution PDF output
        const opt = {
            margin: 0,
            filename: `${title.replace(/\s+/g, '_')}.pdf`,
            image: { type: 'jpeg', quality: 0.98 },
            html2canvas: { 
                scale: 2, 
                useCORS: true, 
                letterRendering: true,
                logging: false,
                scrollX: 0,
                scrollY: 0
            },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        // Use requestAnimationFrame to ensure the menu UI update doesn't block the logic
        requestAnimationFrame(() => {
            try {
                // @ts-ignore - Accessing the global library from index.html
                const exporter = window.html2pdf;
                if (typeof exporter === 'function') {
                    exporter().set(opt).from(element).save();
                } else if (exporter && typeof exporter.default === 'function') {
                    exporter.default().set(opt).from(element).save();
                } else {
                    // Fallback to system print if the library is not found
                    handlePrintSystem(e);
                }
            } catch (err) {
                console.error("PDF engine initialization failed:", err);
                handlePrintSystem(e);
            }
        });
    };

    const handlePrintSystem = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();

        const element = document.getElementById('printable-report-content');
        if (!element) return;

        setShowMenu(false);

        const reportHtml = element.innerHTML;
        const iframe = document.createElement('iframe');

        // Ensure iframe is completely out of view and doesn't disrupt layout
        iframe.style.position = 'fixed';
        iframe.style.right = '100vw';
        iframe.style.bottom = '100vh';
        iframe.style.width = '0';
        iframe.style.height = '0';
        iframe.style.border = '0';
        iframe.style.visibility = 'hidden';

        document.body.appendChild(iframe);
        const iframeWindow = iframe.contentWindow;
        const iframeDoc = iframeWindow?.document;

        if (!iframeDoc || !iframeWindow) {
            document.body.removeChild(iframe);
            return;
        }

        // Professional Document Skeleton for the Print Engine
        iframeDoc.open();
        iframeDoc.write(`
            <!DOCTYPE html>
            <html>
            <head>
                <title>${title}</title>
                <meta charset="UTF-8" />
                <script src="https://cdn.tailwindcss.com"></script>
                <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;700;900&display=swap" rel="stylesheet">
                <style>
                    * { font-family: 'Inter', -apple-system, sans-serif !important; }
                    @page { size: A4; margin: 0; }
                    body { 
                        margin: 0; 
                        padding: 0;
                        -webkit-print-color-adjust: exact !important;
                        print-color-adjust: exact !important;
                    }
                    img { max-width: 100%; height: auto; }
                    .print-container { width: 210mm; margin: 0 auto; }
                </style>
            </head>
            <body>
                <div class="print-container">
                    ${reportHtml}
                </div>
            </body>
            </html>
        `);
        iframeDoc.close();

        // Intelligent print trigger: Wait for Tailwind/Assets to finalize inside the iframe
        const checkReady = setInterval(() => {
            if (iframeDoc.readyState === 'complete') {
                clearInterval(checkReady);
                iframeWindow.focus();

                // Allow a small grace period for image decoding and Tailwind processing
                setTimeout(() => {
                    iframeWindow.print();
                    // Managed cleanup: Wait until user closes the print dialog
                    setTimeout(() => {
                        if (document.body.contains(iframe)) {
                            document.body.removeChild(iframe);
                        }
                    }, 2000);
                }, 750);
            }
        }, 100);
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-md animate-fadeIn no-print">
            <div className="bg-white w-full max-w-5xl h-[94vh] rounded-3xl shadow-2xl flex flex-col overflow-hidden border border-white/20">
