import React, { useState, useRef, useEffect } from 'react';

interface ReportViewerModalProps {
    onClose: () => void;
    onPrint: () => void;
    children: React.ReactNode;
    title: string;
}

const ReportViewerModal: React.FC<ReportViewerModalProps> = ({ 
    onClose, 
    children, 
    title 
}) => {
    const [showMenu, setShowMenu] = useState(false);
    const [isGenerating, setIsGenerating] = useState(false);
    const menuRef = useRef<HTMLDivElement>(null);
    const contentRef = useRef<HTMLDivElement>(null);

    // Close menu when clicking outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setShowMenu(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    /**
     * Professional PDF Generation
     * Uses a cloned element approach to ensure A4 dimensions are 1:1 
     * and unaffected by the preview's CSS transforms/scaling.
     */
    const handleDownloadPdf = async (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();

        if (isGenerating || !contentRef.current) return;

        setIsGenerating(true);
        setShowMenu(false);

        // Professional configuration for high-resolution PDF output
        const opt = {
            margin: 0,
            filename: `${title.replace(/\s+/g, '_')}.pdf`,
            image: { type: 'jpeg', quality: 1.0 },
            html2canvas: { 
                scale: 3, // Ultra-sharp text and graphics
                useCORS: true, 
                letterRendering: true,
                logging: false,
                scrollX: 0,
                scrollY: 0
            },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        try {
            // @ts-ignore - Accessing global html2pdf from index.html
            const exporter = window.html2pdf;

            if (typeof exporter === 'function') {
                // Clone the content to a temporary hidden container to avoid scaling issues
                const clone = contentRef.current.cloneNode(true) as HTMLElement;
                clone.style.position = 'absolute';
                clone.style.left = '-9999px';
                clone.style.top = '0';
                clone.style.transform = 'none'; // CRITICAL: Remove scaling
                clone.style.width = '210mm';
                document.body.appendChild(clone);

                await exporter().set(opt).from(clone).save();

                document.body.removeChild(clone);
            } else {
                console.warn("PDF library missing, falling back to print");
                handlePrintSystem(e);
            }
        } catch (err) {
            console.error("PDF generation failed:", err);
            handlePrintSystem(e);
        } finally {
            setIsGenerating(false);
        }
    };

    /**
     * Professional System Print Fallback
     * Creates a clean iframe environment for the system print dialog.
     */
    const handlePrintSystem = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();

        if (!contentRef.current) return;

        setShowMenu(false);

        const reportHtml = contentRef.current.innerHTML;
        const iframe = document.createElement('iframe');

        // Hide iframe completely
        iframe.style.position = 'fixed';
        iframe.style.right = '100vw';
        iframe.style.bottom = '100vh';
        iframe.style.width = '0';
        iframe.style.height = '0';
        iframe.style.border = '0';

        document.body.appendChild(iframe);
        const iframeWindow = iframe.contentWindow;
        const iframeDoc = iframeWindow?.document;

        if (!iframeDoc || !iframeWindow) {
            document.body.removeChild(iframe);
            return;
        }

        iframeDoc.open();
        iframeDoc.write(`
            <!DOCTYPE html>
            <html>
            <head>
                <title>${title}</title>
                <meta charset="UTF-8" />
                <script src="https://cdn.tailwindcss.com"></script>
                <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;700;900&display=swap" rel="stylesheet">
                <style>
                    * { font-family: 'Inter', sans-serif !important; }
                    @page { size: A4; margin: 0; }
                    body { 
                        margin: 0; 
                        padding: 0;
                        -webkit-print-color-adjust: exact !important;
                        print-color-adjust: exact !important;
                        background: white;
                    }
                    img { max-width: 100%; height: auto; display: block; }
                    .print-wrap { width: 210mm; margin: 0 auto; padding: 0; }
                </style>
            </head>
            <body>
                <div class="print-wrap">
                    ${reportHtml}
                </div>
            </body>
            </html>
        `);
        iframeDoc.close();

        // Wait for iframe assets (Tailwind, Fonts, Images) to be ready
        const checkReady = setInterval(() => {
            if (iframeDoc.readyState === 'complete') {
                clearInterval(checkReady);

                // Ensure all images are actually decoded
                const images = Array.from(iframeDoc.getElementsByTagName('img'));
                const imagePromises = images.map(img => {
                    if (img.complete) return Promise.resolve();
                    return new Promise(resolve => { img.onload = resolve; img.onerror = resolve; });
                });

                Promise.all(imagePromises).then(() => {
                    setTimeout(() => {
                        iframeWindow.focus();
                        iframeWindow.print();
                        // Cleanup after dialog closed
                        setTimeout(() => {
                            if (document.body.contains(iframe)) {
                                document.body.removeChild(iframe);
                            }
                        }, 2000);
                    }, 500);
                });
            }
        }, 100);
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/95 backdrop-blur-md animate-fadeIn no-print">
            <div className="bg-white w-full max-w-5xl h-[94vh] rounded-3xl shadow-2xl flex flex-col overflow-hidden border border-white/20">
                {/* Header Navigation */}
                <div className="px-6 py-4 border-b flex justify-between items-center bg-white border-slate-100 shrink-0">
                    <button 
                        type="button"
                        onClick={onClose}
                        className="text-[10px] font-black text-slate-400 hover:text-slate-900 transition-all uppercase tracking-[0.2em] flex items-center gap-2 px-4 py-2 hover:bg-slate-50 rounded-xl"
                    >
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3"><path d="M15 19l-7-7 7-7" /></svg>
                        Close Preview
                    </button>

                    <div className="relative" ref={menuRef}>
                        <button 
                            type="button"
                            onClick={() => !isGenerating && setShowMenu(!showMenu)}
                            disabled={isGenerating}
                            className={`px-8 py-3.5 text-[10px] font-black text-white rounded-2xl shadow-xl flex items-center gap-3 transition-all active:scale-95 border-t border-white/10 uppercase tracking-[0.2em] ${isGenerating ? 'bg-slate-400' : 'bg-indigo-600 hover:bg-indigo-700'}`}
                        >
                            {isGenerating ? (
                                <svg className="animate-spin h-4 w-4 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                            ) : (
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2.5"><path d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                            )}
                            {isGenerating ? 'Generating...' : 'Print / Save PDF'}
                            <svg className={`w-3 h-3 transition-transform duration-300 ${showMenu ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3"><path d="M19 9l-7 7-7-7" /></svg>
                        </button>

                        {showMenu && (
                            <div className="absolute top-full right-0 mt-3 w-64 bg-white rounded-3xl shadow-2xl border border-slate-100 py-2.5 z-[70] animate-fadeIn origin-top-right ring-1 ring-black/5">
                                <button 
                                    type="button"
                                    onClick={handleDownloadPdf}
                                    className="w-full px-5 py-4 text-left flex items-center gap-4 hover:bg-slate-50 transition-colors group"
                                >
                                    <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2.5"><path d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                    </div>
                                    <div>
                                        <p className="text-[11px] font-black text-slate-800 uppercase tracking-tight">Download PDF</p>
                                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-wider">High-Res Digital Copy</p>
                                    </div>
                                </button>

                                <div className="h-px bg-slate-100 mx-4 my-1" />

                                <button 
                                    type="button"
                                    onClick={handlePrintSystem}
                                    className="w-full px-5 py-4 text-left flex items-center gap-4 hover:bg-slate-50 transition-colors group"
                                >
                                    <div className="w-10 h-10 bg-slate-50 text-slate-400 rounded-xl flex items-center justify-center group-hover:bg-slate-900 group-hover:text-white transition-colors">
                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2.5"><path d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                                    </div>
                                    <div>
                                        <p className="text-[11px] font-black text-slate-800 uppercase tracking-tight">System Print</p>
                                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-wider">Printer / Save as PDF</p>
                                    </div>
                                </button>
                            </div>
                        )}
                    </div>
                </div>

                {/* Report Content Viewer Area */}
                <div className="flex-1 overflow-auto bg-slate-100 p-4 sm:p-10 flex justify-center scrollbar-hide">
                    <div className="origin-top transform scale-[0.6] xs:scale-[0.75] sm:scale-[0.85] lg:scale-100 transition-transform duration-500">
                         <div 
                            ref={contentRef}
                            className="bg-white shadow-2xl min-h-[297mm] relative z-10 w-[210mm] print:shadow-none box-border mb-20"
                        >
                            {children}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

