import React, { useState, useRef, useEffect } from 'react';

interface ReportViewerModalProps {
    onClose: () => void;
    onPrint: () => void;
    children: React.ReactNode;
    title: string;
}

const ReportViewerModal: React.FC<ReportViewerModalProps> = ({ 
    onClose, 
    children, 
    title 
}) => {
    const [showMenu, setShowMenu] = useState(false);
    const [isGenerating, setIsGenerating] = useState(false);
    const [genMessage, setGenMessage] = useState('Print / Save PDF');
    const menuRef = useRef<HTMLDivElement>(null);
    const contentRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setShowMenu(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    /**
     * Professional Asset Pre-loader
     * Ensures images and signatures are fully ready for the canvas engine
     */
    const preloadAssets = async (container: HTMLElement) => {
        const images = Array.from(container.getElementsByTagName('img'));
        const promises = images.map(img => {
            return new Promise((resolve) => {
                if (img.complete && img.naturalHeight !== 0) {
                    resolve(true);
                } else {
                    img.onload = () => resolve(true);
                    img.onerror = () => resolve(false);
                    // Force re-trigger for cached images
                    const src = img.src;
                    img.src = src;
                }
            });
        });
        return Promise.all(promises);
    };

    const handleDownloadPdf = async (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();

        if (isGenerating || !contentRef.current) return;

        const exporter = (window as any).html2pdf;
        if (!exporter) {
            alert("PDF Engine loading. Please wait a moment and try again.");
            return;
        }

        setIsGenerating(true);
        setShowMenu(false);
        setGenMessage('Initializing...');

        // 1. Prepare Shadow Container
        // We need the element to be "visible" for html2canvas to see it, 
        // but we hide it from the user with fixed positioning and high z-index loading state.
        const shadowContainer = document.createElement('div');
        shadowContainer.style.position = 'fixed';
        shadowContainer.style.top = '0';
        shadowContainer.style.left = '0';
        shadowContainer.style.width = '210mm'; // Standard A4 width
        shadowContainer.style.backgroundColor = 'white';
        shadowContainer.style.zIndex = '1'; // Must be visible to the engine
        shadowContainer.style.opacity = '0.01'; // Minimal opacity ensures rendering but invisible to user
        shadowContainer.style.pointerEvents = 'none';

        const clone = contentRef.current.cloneNode(true) as HTMLElement;
        clone.style.transform = 'none';
        clone.style.margin = '0';
        clone.style.padding = '0';
        clone.style.boxShadow = 'none';
        clone.style.display = 'block';

        shadowContainer.appendChild(clone);
        document.body.appendChild(shadowContainer);

        try {
            setGenMessage('Syncing Assets...');
            await preloadAssets(shadowContainer);

            // Force browser layout calculation (Reflow)
            // This is critical to ensure the blank page issue is resolved
            void shadowContainer.offsetHeight; 

            setGenMessage('Rendering PDF...');

            const opt = {
                margin: 0,
                filename: `${title.replace(/\s+/g, '_')}.pdf`,
                image: { type: 'jpeg', quality: 0.98 },
                html2canvas: { 
                    scale: 2, // Higher scale for clarity
                    useCORS: true,
                    logging: false,
                    letterRendering: true,
                    allowTaint: false,
                    scrollY: 0,
                    scrollX: 0,
                    windowWidth: shadowContainer.offsetWidth
                },
                jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait', compress: true }
            };

            await exporter().set(opt).from(shadowContainer).save();
            setGenMessage('Download Started');
        } catch (err) {
            console.error("PDF Generation Error:", err);
            setGenMessage('Engine Error');
        } finally {
            // Cleanup
            if (document.body.contains(shadowContainer)) {
                document.body.removeChild(shadowContainer);
            }
            setTimeout(() => {
                setIsGenerating(false);
                setGenMessage('Print / Save PDF');
            }, 1500);
        }
    };

    const handlePrintSystem = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (!contentRef.current) return;
        setShowMenu(false);

        const reportHtml = contentRef.current.innerHTML;
        const iframe = document.createElement('iframe');
        iframe.style.position = 'fixed';
        iframe.style.right = '100vw';
        iframe.style.bottom = '100vh';
        iframe.style.width = '0';
        iframe.style.height = '0';
        iframe.style.border = '0';

        document.body.appendChild(iframe);
        const iframeDoc = iframe.contentWindow?.document;
        if (!iframeDoc) return;

        iframeDoc.open();
        iframeDoc.write(`
            <!DOCTYPE html>
            <html>
            <head>
                <title>${title}</title>
                <meta charset="UTF-8" />
                <script src="https://cdn.tailwindcss.com"></script>
                <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;700;900&display=swap" rel="stylesheet">
                <style>
                    @page { size: A4; margin: 0; }
                    body { margin: 0; padding: 0; -webkit-print-color-adjust: exact !important; font-family: 'Inter', sans-serif !important; }
                    img { max-width: 100%; height: auto; display: block; }
                    .print-wrap { width: 210mm; margin: 0 auto; }
                </style>
            </head>
            <body>
                <div class="print-wrap">${reportHtml}</div>
            </body>
            </html>
        `);
        iframeDoc.close();

        const checkReady = setInterval(() => {
            if (iframeDoc.readyState === 'complete') {
                clearInterval(checkReady);
                const images = Array.from(iframeDoc.getElementsByTagName('img'));
                Promise.all(images.map(img => img.complete ? Promise.resolve() : new Promise(res => img.onload = res))).then(() => {
                    setTimeout(() => {
                        iframe.contentWindow?.focus();
                        iframe.contentWindow?.print();
                        setTimeout(() => document.body.removeChild(iframe), 2000);
                    }, 500);
                });
            }
        }, 100);
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/95 backdrop-blur-md animate-fadeIn no-print">
            {/* Generation Progress Overlay */}
            {isGenerating && (
