/**
 * 1_Controller.gs - Main entry points and request routing.
 */

export const CODE_1_CONTROLLER = `/**
 * 1_Controller.gs - Main entry points and request routing.
 */

function doPost(e) {
  const lock = LockService.getScriptLock();
  // Professional 30s lock to prevent race conditions during multi-user submissions
  lock.tryLock(30000); 

  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const body = e.postData ? JSON.parse(e.postData.contents) : {};
    return routeRequest(ss, body);
  } catch (err) {
    return ResponseBuilder.error("System Exception: " + err.toString());
  } finally {
    lock.releaseLock();
  }
}

function doGet(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  return DataHandlers.handleGetRequest(ss);
}

function routeRequest(ss, body) {
  const action = body.action;
  const routes = {
    'login': () => AuthHandlers.handleLogin(ss, body),
    'register_user': () => AuthHandlers.handleRegisterUser(ss, body),
    'get_users': () => AuthHandlers.handleGetUsers(ss),
    'delete_user': () => AuthHandlers.handleDeleteUser(ss, body),
    'update_user': () => AuthHandlers.handleUpdateUser(ss, body),
    'heartbeat': () => AuthHandlers.handleHeartbeat(ss, body),
    'mark_read': () => AuthHandlers.handleMarkRead(ss, body),
    'manage_fleet': () => SystemHandlers.handleManageFleet(ss, body),
    'bulk_manage_fleet': () => SystemHandlers.handleBulkManageFleet(ss, body),
    'acknowledge_issue': () => SystemHandlers.handleAcknowledgeIssue(ss, body),
    'request_inspection': () => SystemHandlers.handleRequestInspection(ss, body),
    'get_acknowledgements': () => SystemHandlers.handleGetAcknowledgements(ss),
    'mark_notification_read': () => SystemHandlers.handleMarkNotificationRead(ss, body),
    'update_settings': () => SystemHandlers.handleUpdateSettings(ss, body),
    'broadcast': () => SystemHandlers.handleBroadcast(ss, body),
    'acknowledge_notification': () => SystemHandlers.handleAcknowledgeNotification(ss, body),
    'check_subscription': () => SubscriptionHandlers.handleCheckSubscription(ss),
    'extend_subscription': () => SubscriptionHandlers.handleExtendSubscription(ss, body),
    'submit_support_ticket': () => SupportHandlers.handleSubmitSupport(ss, body),
    'get_tickets': () => SupportHandlers.handleGetTickets(ss, body),
    'update_ticket': () => SupportHandlers.handleUpdateTicket(ss, body),
    'initiate_mobile_payment': () => PaymentHandlers.handleMobileMoney(ss, body),
    'generate_report_pdf': () => SystemHandlers.handleGenerateReportPDF(ss, body)
  };

  if (!action || action === 'create' || !routes[action]) {
    return DataHandlers.handleDataSubmission(ss, body);
  }
  return routes[action]();
}`;

/**
 * 3_CoreOperations.gs - Core Data Flow & Systems
 */

export const CODE_3_CORE_OPERATIONS = `/**
 * 3_CoreOperations.gs - Core Data Flow & Systems
 */

const DataHandlers = {
  handleDataSubmission: function(ss, body) {
    const sheetName = body.sheet;
    const rowData = body.row;
    let sheet = ss.getSheetByName(sheetName);

    if (!sheet) return ResponseBuilder.error("Target registry '" + sheetName + "' not found.");

    const safeRow = rowData.map(r => (r === null || r === undefined) ? "" : String(r));
    sheet.appendRow(safeRow);

    // Track original request completion
    if (body.requestId) {
        const reqSheet = ss.getSheetByName('Inspection_Requests');
        if (reqSheet) {
            const reqData = reqSheet.getDataRange().getValues();
            for (let i = 1; i < reqData.length; i++) {
                if (String(reqData[i][0]) === String(body.requestId)) {
                    reqSheet.getRange(i + 1, 10).setValue('Completed');
                    break;
                }
            }
        }
    }

    // DISPATCH EMAIL NOTIFICATIONS
    if (typeof EmailHandlers !== 'undefined') {
       EmailHandlers.sendEmailNotifications(ss, body, sheetName);
    }

    // UPDATE AUTO-SUGGESTION REGISTRY
    if (typeof Validation !== 'undefined') {
       Validation.updateFromRow(ss, body);
    }

    return ResponseBuilder.success({ sheet: sheetName });
  },

  handleGetRequest: function(ss) {
    const sheets = ss.getSheets();
    const data = {};
    sheets.forEach(sheet => {
      const name = sheet.getName();
      if (name === 'Users' || name === 'System_Logs') return;

      const lastRow = sheet.getLastRow();
      if (lastRow === 0) {
          data[name] = [];
          return;
      }

      if (name === 'Validation_Data') {
         if (lastRow > 1) {
            const range = sheet.getRange(2, 1, lastRow - 1, sheet.getLastColumn());
            const values = range.getValues();
            const columns = {};
            const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
            headers.forEach((h, colIndex) => {
               columns[h] = [...new Set(values.map(row => row[colIndex]).filter(c => c !== ""))]; 
            });
            data[name] = columns;
         } else { data[name] = {}; }
      } else if (name === 'System_Settings') {
          data[name] = sheet.getDataRange().getValues();
      } else if (name === 'Subscription_Data') {
          const values = sheet.getDataRange().getValues();
          if (values.length > 1) {
            const lastRow = values[values.length - 1];
            data[name] = { 
                current: { status: lastRow[0], plan: lastRow[1], expiryDate: lastRow[2], processedBy: lastRow[3] },
                history: values.slice(1).map(r => ({ status: r[0], plan: r[1], expiryDate: r[2], processedBy: r[3], timestamp: r[4] }))
            };
          } else { data[name] = { current: { status: "Expired" }, history: [] }; }
      } else {
         const startRow = Math.max(1, lastRow - 300);
         const values = sheet.getRange(startRow, 1, lastRow - startRow + 1, sheet.getLastColumn()).getValues();
         if (startRow > 1) values.unshift(sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0]);
         data[name] = values;
      }
    });
    return ResponseBuilder.build(data);
  }
};

const SystemHandlers = {
  handleBroadcast: function(ss, body) {
    const sheet = ss.getSheetByName('Messages');
    if (!sheet) return ResponseBuilder.error("Messages system offline.");
    sheet.appendRow([Date.now(), "SYSTEM", "Automated Console", "ALL", "[BROADCAST]: " + body.message, new Date().toISOString(), "Sent"]);
    return ResponseBuilder.success();
  },

  handleRequestInspection: function(ss, body) {
    let sheet = ss.getSheetByName('Inspection_Requests');
    if (!sheet) {
        sheet = ss.insertSheet('Inspection_Requests');
        sheet.appendRow(['ID', 'Requester', 'Role', 'Truck', 'Trailer', 'Type', 'Reason', 'Priority', 'AssignedTo', 'Status', 'Timestamp']);
    }
    const requestId = "REQ-" + Date.now();
    sheet.appendRow([requestId, body.requester, body.role, body.truckNo, body.trailerNo || "", body.type, body.reason, body.priority, body.assignedInspector || "Unassigned", "Pending", new Date().toISOString()]);
    return ResponseBuilder.success({ requestId });
  },

  handleUpdateSettings: function(ss, body) {
    let sheet = ss.getSheetByName('System_Settings');
    if (!sheet) {
        sheet = ss.insertSheet('System_Settings');
        sheet.appendRow(['Company_Name', 'Manager_Email', 'Last_Updated', 'Updated_By', 'Maintenance_Mode', 'Logo_Data', 'Mobile_Link', 'Web_Link', 'Maintenance_Msg', 'Payment_Key']);
    }
    const row = [body.companyName, body.managerEmail, new Date(), "Admin", body.maintenanceMode ? "TRUE" : "FALSE", body.companyLogo, body.mobileApkLink, body.webAppUrl, body.maintenanceMessage, body.flutterwaveSecretKey];
    if (sheet.getLastRow() < 2) sheet.appendRow(row);
    else sheet.getRange(2, 1, 1, row.length).setValues([row]);
    return ResponseBuilder.success();
  },

  /**
   * Professional Server-Side PDF Generator
   * Eliminates blank pages by rendering HTML in the cloud
   */
  handleGenerateReportPDF: function(ss, body) {
    try {
      if (!body.reportData) return ResponseBuilder.error("Missing report data payload.");

      const reportHtml = PDFGenerator.create(body.reportData);
      const blob = Utilities.newBlob(reportHtml, 'text/html').getAs('application/pdf');
      const base64Pdf = Utilities.base64Encode(blob.getBytes());

      return ResponseBuilder.success({ 
        base64: base64Pdf,
        filename: (body.reportData.truckNo || "Report") + "_Inspection.pdf"
      });
    } catch (err) {
      return ResponseBuilder.error("PDF Engine Error: " + err.toString());
    }
  }
};

const SubscriptionHandlers = {
  handleCheckSubscription: function(ss) {
    const sheet = ss.getSheetByName('Subscription_Data');
    if (!sheet || sheet.getLastRow() < 2) return ResponseBuilder.success({ status: "Expired" });
    const lastRow = sheet.getRange(sheet.getLastRow(), 1, 1, 4).getValues()[0];
    return ResponseBuilder.success({ status: lastRow[0], plan: lastRow[1], expiryDate: lastRow[2] });
  },
  handleExtendSubscription: function(ss, body) {
    let sheet = ss.getSheetByName('Subscription_Data');
    if (!sheet) {
      sheet = ss.insertSheet('Subscription_Data');
      sheet.appendRow(['Status', 'Plan', 'ExpiryDate', 'ProcessedBy', 'Timestamp']);
    }
    sheet.appendRow([body.status || "Active", body.plan || "Standard", body.expiryDate, "Admin", new Date().toISOString()]);
    return ResponseBuilder.success();
  }
};

const PaymentHandlers = {
  handleMobileMoney: function(ss, body) {
    // Placeholder for Flutterwave / Zambian Gateway logic
    return ResponseBuilder.success({ message: "Mock Payment: Payment prompt sent to " + body.phoneNumber });
  }
};`;

import React from 'react';
import { User, SystemSettings, InspectionData, ValidationLists } from '../../types';

// UI Components
import ProfileModal from '../ui/ProfileModal';
import SolutionsDrawer from '../ui/SolutionsDrawer';
import RequestInspectionModal from '../ui/RequestInspectionModal';
import InspectionStartModal from '../ui/InspectionStartModal';
import ReportViewerModal from '../ui/ReportViewerModal';

// Report Components
import PrintableGeneralReport from '../reports/PrintableGeneralReport';
import PrintablePetroleumReport from '../reports/PrintablePetroleumReport';
import PrintablePetroleumV2Report from '../reports/PrintablePetroleumV2Report';
import PrintableAcidReport from '../reports/PrintableAcidReport';

import { INSPECTION_ITEMS, PETROLEUM_INSPECTION_ITEMS, PETROLEUM_V2_ITEMS, ACID_INSPECTION_ITEMS } from '../../constants';

interface AppModalsProps {
    isProfileModalOpen: boolean;
    isSolutionsOpen: boolean;
    isRequestModalOpen: boolean;
    isStartModalOpen: boolean;
    isReportModalOpen: boolean;
    currentUser: User;
    settings: SystemSettings;
    appScriptUrl: string;
    validationLists: ValidationLists;
    hasExistingDraft: boolean;
    pendingModule: string | null;
    activeModule: string;
    selectedReportData: InspectionData | null;

    setIsProfileModalOpen: (open: boolean) => void;
    setIsSolutionsOpen: (open: boolean) => void;
    setIsRequestModalOpen: (open: boolean) => void;
    setIsStartModalOpen: (open: boolean) => void;
    setIsReportModalOpen: (open: boolean) => void;

    showToast: any;
    setCurrentUser: (user: User) => void;
    handleLogout: () => void;
    handleNavigate: (module: string) => void;
    handleRequestSubmit: (data: any) => void;
    handleDiscardAndStartNew: () => void;
    handleResumeDraft: () => void;
}

const AppModals: React.FC<AppModalsProps> = ({
    isProfileModalOpen, isSolutionsOpen, isRequestModalOpen, isStartModalOpen, isReportModalOpen,
    currentUser, settings, appScriptUrl, validationLists, hasExistingDraft, pendingModule, activeModule, selectedReportData,
    setIsProfileModalOpen, setIsSolutionsOpen, setIsRequestModalOpen, setIsStartModalOpen, setIsReportModalOpen,
    showToast, setCurrentUser, handleLogout, handleNavigate, handleRequestSubmit, handleDiscardAndStartNew, handleResumeDraft
}) => {

    // Robust template detection based on data payload instead of UI state
    const renderReportTemplate = (data: InspectionData) => {
        if (data.petro_1 !== undefined) {
            return <PrintablePetroleumReport data={data} settings={settings} />;
        }
        if (data.petro2_1 !== undefined) {
            return <PrintablePetroleumV2Report data={data} settings={settings} />;
        }
        if (data.acid_1 !== undefined) {
            return <PrintableAcidReport data={data} settings={settings} />;
        }
        return <PrintableGeneralReport data={data} settings={settings} />;
    };

    const getReportTitle = (data: InspectionData) => {
        if (data.petro_1 !== undefined) return 'Petroleum_V1';
        if (data.petro2_1 !== undefined) return 'Petroleum_V2';
        if (data.acid_1 !== undefined) return 'Acid_Tanker';
        return 'General_Vehicle';
    };

    const getReportPayload = (data: InspectionData) => {
        let title = "General Vehicle Inspection";
        let activeItems = INSPECTION_ITEMS;

        if (data.petro_1 !== undefined) {
            title = "Petroleum Tanker Inspection";
            activeItems = PETROLEUM_INSPECTION_ITEMS;
        } else if (data.petro2_1 !== undefined) {
            title = "Petroleum Tanker Inspection V2";
            activeItems = PETROLEUM_V2_ITEMS;
        } else if (data.acid_1 !== undefined) {
            title = "Acid Tanker Inspection";
            activeItems = ACID_INSPECTION_ITEMS;
        }

        return {
            title: title, 
            timestamp: data.timestamp || new Date().toISOString(), 
            truckNo: data.truckNo || 'N/A', 
            trailerNo: data.trailerNo || 'N/A', 
            jobCard: data.jobCard || '',
            location: data.location || 'N/A', 
            odometer: data.odometer || '0', 
            inspectedBy: data.inspectedBy || currentUser?.name || 'Inspector', 
            driverName: data.driverName || 'N/A',
            remarks: data.remarks || '', 
            rate: data.rate || 0, 
            safeToLoad: data.safeToLoad || 'Not Specified', 
            signatures: { 
                inspector: data.inspectorSignature || null, 
                driver: data.driverSignature || null 
            },
            photos: { 
                front: data.photoFront || null, 
                ls: data.photoLS || null, 
                rs: data.photoRS || null, 
                back: data.photoBack || null, 
                damage: data.photoDamage || null 
            },
            items: activeItems.map(item => ({ 
                label: item.label, 
                category: item.category, 
                status: data[item.id] || 'N/A' 
            })),
            companyName: settings.companyName || 'Fleet Portal', 
            companyLogo: settings.companyLogo || null
        };
    };

    return (
        <>
            {isProfileModalOpen && (
                <ProfileModal 
                    user={currentUser} 
                    settings={settings} 
                    appScriptUrl={appScriptUrl} 
                    onClose={() => setIsProfileModalOpen(false)} 
                    showToast={showToast} 
                    onUpdateSuccess={(u) => setCurrentUser(u)} 
                    onLogout={() => { setIsProfileModalOpen(false); handleLogout(); }} 
                />
            )}

            {isSolutionsOpen && (
                <SolutionsDrawer isOpen={isSolutionsOpen} onClose={() => setIsSolutionsOpen(false)} onAction={handleNavigate} />
            )}

            <RequestInspectionModal 
                isOpen={isRequestModalOpen} 
                onClose={() => setIsRequestModalOpen(false)} 
                onSubmit={handleRequestSubmit} 
                validationLists={validationLists} 
                currentUserRole={currentUser.role} 
            />

            <InspectionStartModal 
                isOpen={isStartModalOpen} 
                onClose={() => setIsStartModalOpen(false)} 
                onStartNew={handleDiscardAndStartNew} 
                onResume={handleResumeDraft} 
                hasDraft={hasExistingDraft} 
                moduleName={pendingModule || ''} 
            />

            {isReportModalOpen && selectedReportData && (
                <ReportViewerModal 
                    onClose={() => setIsReportModalOpen(false)} 
                    onPrint={() => window.print()} 
                    title={`${getReportTitle(selectedReportData)}_${selectedReportData.truckNo || 'Unit'}`}
                    appScriptUrl={appScriptUrl}
                    reportPayload={getReportPayload(selectedReportData)}
                >
                    {renderReportTemplate(selectedReportData)}
                </ReportViewerModal>
            )}
        </>
    );
};

export default AppModals;

import React, { useState, useRef, useEffect } from 'react';

interface ReportViewerModalProps {
    onClose: () => void;
    onPrint: () => void;
    children: React.ReactNode;
    title: string;
    appScriptUrl?: string;
    reportPayload?: any;
}

const ReportViewerModal: React.FC<ReportViewerModalProps> = ({ 
    onClose, 
    children, 
    title,
    appScriptUrl,
    reportPayload
}) => {
    const [showMenu, setShowMenu] = useState(false);
    const [isGenerating, setIsGenerating] = useState(false);
    const [genMessage, setGenMessage] = useState('Print / Save PDF');
    const menuRef = useRef<HTMLDivElement>(null);
    const contentRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setShowMenu(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    /**
     * Professional Enterprise Cloud Rendering
     * Sends data to Google Apps Script to generate a guaranteed high-fidelity PDF.
     */
    const handleDownloadPdf = async (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();

        if (isGenerating || !appScriptUrl || !reportPayload) return;

        setIsGenerating(true);
        setShowMenu(false);
        setGenMessage('Cloud Rendering...');

        try {
            const response = await fetch(appScriptUrl, {
                method: 'POST',
                body: JSON.stringify({
                    action: 'generate_report_pdf',
                    reportData: reportPayload
                })
            });

            const result = await response.json();

            if (result.status === 'success' && result.base64) {
                setGenMessage('Preparing Download...');

                // Construct a virtual link to trigger the browser's download
                const linkSource = `data:application/pdf;base64,${result.base64}`;
                const downloadLink = document.createElement("a");
                const fileName = result.filename || `${title}.pdf`;

                downloadLink.href = linkSource;
                downloadLink.download = fileName;
                downloadLink.click();

                setGenMessage('Complete');
            } else {
                throw new Error(result.message || "Failed to render PDF in the cloud.");
            }
        } catch (err) {
            console.error("Professional Render Failed:", err);
            setGenMessage('Cloud Error');
            alert("Digital rendering service is temporarily busy. Please try 'System Print' as a fallback.");
        } finally {
            setTimeout(() => {
                setIsGenerating(false);
                setGenMessage('Print / Save PDF');
            }, 2000);
        }
    };

    const handlePrintSystem = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (!contentRef.current) return;
        setShowMenu(false);

        const reportHtml = contentRef.current.innerHTML;
        const iframe = document.createElement('iframe');
        iframe.style.position = 'fixed';
        iframe.style.right = '100vw';
        iframe.style.bottom = '100vh';
        iframe.style.width = '0';
        iframe.style.height = '0';
        iframe.style.border = '0';

        document.body.appendChild(iframe);
        const iframeDoc = iframe.contentWindow?.document;
        if (!iframeDoc) return;

        iframeDoc.open();
        iframeDoc.write(`
            <!DOCTYPE html>
            <html>
            <head>
                <title>${title}</title>
                <meta charset="UTF-8" />
                <script src="https://cdn.tailwindcss.com"></script>
                <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;700;900&display=swap" rel="stylesheet">
                <style>
                    @page { size: A4; margin: 0; }
                    body { margin: 0; padding: 0; -webkit-print-color-adjust: exact !important; font-family: 'Inter', sans-serif !important; }
                    img { max-width: 100%; height: auto; display: block; }
                    .print-wrap { width: 210mm; margin: 0 auto; }
                </style>
            </head>
            <body>
                <div class="print-wrap">${reportHtml}</div>
            </body>
            </html>
        `);
        iframeDoc.close();

        const checkReady = setInterval(() => {
            if (iframeDoc.readyState === 'complete') {
                clearInterval(checkReady);
                const images = Array.from(iframeDoc.getElementsByTagName('img'));
                Promise.all(images.map(img => img.complete ? Promise.resolve() : new Promise(res => img.onload = res))).then(() => {
                    setTimeout(() => {
                        iframe.contentWindow?.focus();
                        iframe.contentWindow?.print();
                        setTimeout(() => document.body.removeChild(iframe), 2000);
                    }, 500);
                });
            }
        }, 100);
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/95 backdrop-blur-md animate-fadeIn no-print">
